// Plus Two entrance chemistry bank: Chemical kinetics (Class 12). Original fibub questions.
// Data used: ln 2 = 0.693; log 2 = 0.301, log 3 = 0.477, log 5 = 0.699, log 7 = 0.845; R = 8.314 J/(mol K); first order: k = (2.303/t) log([A]0/[A]).
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';
let _n = 0;
const EXM = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 3: ['jee-main', 'neet', 'comedk', 'cuet'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const L = [];
const mkx = (level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { type: 'mcq', level, format: 'single', exams: EXM[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const mk = (...a) => { L.push(mkx(...a)); };
const nat = (level, sub, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const msq = (level, sub, q, options, answer, sol, trap) => { L.push({ type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const asr = (level, sub, A, R, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'assertion', exams: EXM[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) }); };
const stm = (level, sub, s1, s2, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'statements', exams: EXM[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) }); };
const mat = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'match', group }); };
const P = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'passage', group }); };
const PN = (level, sub, group, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: 'passage', exams: EX[level], sub, group, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const l10 = Math.log10;
const F = 96500;
// ---------- Level 1 ----------
mk(1, 'rate of reaction', 'The rate of a chemical reaction is best defined as', 'the change in concentration of a reactant or product per unit time', ['the total amount of product formed at the end', 'the time taken for the reaction to start', 'the energy released per mole of reactant'], '<p>Rate = -&Delta;[reactant]/&Delta;t = +&Delta;[product]/&Delta;t. It tells how fast concentration changes, not how much product finally forms (that is yield) nor energy (that is enthalpy).</p>');
mk(1, 'units of rate', 'The usual unit of the rate of a reaction in solution is', 'mol L<sup>-1</sup> s<sup>-1</sup>', ['s<sup>-1</sup>', 'L mol<sup>-1</sup> s<sup>-1</sup>', 'mol s'], '<p>Rate is concentration (mol L<sup>-1</sup>) divided by time (s), so mol L<sup>-1</sup> s<sup>-1</sup>. The other units belong to rate constants of first and second order reactions.</p>');
mk(1, 'order of reaction', 'For the rate law rate = k[A]<sup>2</sup>[B], the overall order of the reaction is', '3', ['2', '1', '4'], '<p>Overall order is the sum of the powers of the concentrations in the rate law: 2 + 1 = 3. The order is read from the rate law, not from the balanced equation.</p>');
mk(1, 'molecularity', 'Molecularity of an elementary reaction', 'is always a whole number, never zero or fractional', ['can be zero', 'can be a fraction such as 1/2', 'is always equal to the sum of the stoichiometric coefficients of the overall reaction'], '<p>Molecularity is the number of reacting species colliding in one elementary step: 1, 2 or (rarely) 3. It is a whole number. It applies to a single step, not to a multi-step reaction as a whole.</p>');
mk(1, 'units of k', 'The unit of the rate constant of a first order reaction is', 's<sup>-1</sup>', ['mol L<sup>-1</sup> s<sup>-1</sup>', 'L mol<sup>-1</sup> s<sup>-1</sup>', 'mol<sup>2</sup> L<sup>-2</sup> s<sup>-1</sup>'], '<p>For first order, rate = k[A], so k = rate/[A] = (mol L<sup>-1</sup> s<sup>-1</sup>)/(mol L<sup>-1</sup>) = s<sup>-1</sup>.</p>');
nat(1, 'half-life', 'A first order reaction has k = 0.0693 min<sup>-1</sup>. Find its half-life in minutes. (ln 2 = 0.693)', 10, 0, 'min', '<p>For first order, t<sub>1/2</sub> = 0.693/k = 0.693/0.0693 = <b>10 min</b>.</p>', '', () => 0.693 / 0.0693);
nat(1, 'order of reaction', 'The rate law of a reaction is rate = k[A][B]<sup>2</sup>. What is the overall order?', 3, 0, '', '<p>Add the powers: 1 + 2 = <b>3</b>.</p>', '', () => 3);
mk(1, 'Arrhenius equation', 'The Arrhenius equation is', 'k = A e<sup>-E<sub>a</sub>/RT</sup>', ['k = A e<sup>E<sub>a</sub>/RT</sup>', 'k = A e<sup>-RT/E<sub>a</sub></sup>', 'k = E<sub>a</sub> e<sup>-A/RT</sup>'], '<p>k = A e<sup>-E<sub>a</sub>/RT</sup>, where A is the frequency (pre-exponential) factor. The negative sign means higher activation energy gives a smaller k, and higher T gives a larger k.</p>');
mk(1, 'catalyst', 'A catalyst increases the rate of a reaction by', 'providing a path with lower activation energy', ['increasing the temperature of the system', 'increasing the enthalpy change of the reaction', 'shifting the equilibrium towards the products'], '<p>A catalyst offers an alternative route with a lower E<sub>a</sub>, so more molecules cross the barrier. It does not change &Delta;H or the equilibrium constant, and it is not used up.</p>');
mk(1, 'half-life of zero order', 'For a zero order reaction, the half-life', 'is directly proportional to the initial concentration', ['is independent of the initial concentration', 'is inversely proportional to the initial concentration', 'is proportional to the square of the initial concentration'], '<p>For zero order t<sub>1/2</sub> = [A]<sub>0</sub>/(2k). More starting material takes longer to be halved at a constant rate.</p>');
mk(1, 'temperature coefficient', 'For most reactions near room temperature, a 10 K rise in temperature makes the rate about', 'two to three times larger', ['ten times larger', 'half as large', 'unchanged'], '<p>The temperature coefficient (rate at T + 10 over rate at T) is typically 2 to 3, as described in the Arrhenius equation. This is a rule of thumb, not an exact law.</p>');
mk(1, 'collision theory', 'According to collision theory, a collision leads to reaction only if the molecules have', 'energy at least equal to the threshold energy and the proper orientation', ['equal speeds and equal masses', 'proper orientation only', 'energy equal to the activation energy of the reverse reaction'], '<p>Effective collisions need (i) enough energy (at least the threshold energy) and (ii) the right orientation. Most collisions fail one or both tests.</p>');
mk(1, 'radioactive decay', 'Radioactive decay follows', 'first order kinetics', ['zero order kinetics', 'second order kinetics', 'no fixed order'], '<p>The decay rate is proportional to the number of undecayed nuclei, -dN/dt = &lambda;N, which is the first order law. That is why every radioactive nuclide has a fixed half-life.</p>');
nat(1, 'rate and stoichiometry', 'For 2A &rarr; B, the rate of disappearance of A is 0.04 mol L<sup>-1</sup> s<sup>-1</sup>. Find the rate of reaction, defined as -&frac12; d[A]/dt, in mol L<sup>-1</sup> s<sup>-1</sup>.', 0.02, 0.001, 'mol L<sup>-1</sup> s<sup>-1</sup>', '<p>Rate of reaction = -(1/2) d[A]/dt = 0.04/2 = <b>0.02</b>. Dividing by the stoichiometric coefficient gives one common rate.</p>', '', () => 0.04 / 2);
mk(1, 'rate determining step', 'In a multi-step reaction the overall rate is controlled by', 'the slowest step', ['the fastest step', 'the last step', 'the step with the most reactants'], '<p>Like the narrowest part of a pipe, the slowest elementary step (the rate-determining step) sets the overall rate.</p>');
mk(1, 'units of k', 'The unit of the rate constant of a zero order reaction is', 'mol L<sup>-1</sup> s<sup>-1</sup>', ['s<sup>-1</sup>', 'L mol<sup>-1</sup> s<sup>-1</sup>', 'it has no unit'], '<p>For zero order, rate = k, so k has the same unit as rate: mol L<sup>-1</sup> s<sup>-1</sup>.</p>');
// ---------- Level 2 ----------
nat(2, 'first order half-life', 'A first order reaction has a half-life of 20 min. Find the rate constant in min<sup>-1</sup>.', 0.0347, 0.0005, 'min<sup>-1</sup>', '<p>k = 0.693/t<sub>1/2</sub> = 0.693/20 = <b>0.0347 min<sup>-1</sup></b>.</p>', '', () => 0.693 / 20);
nat(2, 'first order', 'The half-life of a first order reaction is 10 min. How long does it take for 75 % of the reactant to be consumed?', 20, 0, 'min', '<p>75 % consumed leaves 25 % = 1/4, which is two half-lives.</p><p>t = 2 &times; 10 = <b>20 min</b>.</p>', '', () => 2 * 10);
nat(2, 'first order integrated law', 'In a first order reaction 20 % of the reactant decomposes in 10 min. Find k in min<sup>-1</sup>. (log 1.25 = 0.0969)', 0.0223, 0.0005, 'min<sup>-1</sup>', '<p>[A]<sub>0</sub> = 100, [A] = 80. k = (2.303/t) log([A]<sub>0</sub>/[A]) = (2.303/10) log(100/80).</p><p>= 0.2303 &times; 0.0969 = <b>0.0223 min<sup>-1</sup></b>.</p>', 'Use the amount left (80), not the amount reacted (20).', () => 2.303 / 10 * 0.0969);
nat(2, 'zero order half-life', 'For a zero order reaction [A]<sub>0</sub> = 0.80 M and k = 0.020 mol L<sup>-1</sup> s<sup>-1</sup>. Find the half-life in seconds.', 20, 0, 's', '<p>For zero order t<sub>1/2</sub> = [A]<sub>0</sub>/(2k) = 0.80/(2 &times; 0.020) = <b>20 s</b>.</p>', 'Do not use 0.693/k here.', () => 0.8 / (2 * 0.02));
nat(2, 'initial rate method', 'In an experiment, doubling [A] doubles the rate and doubling [B] quadruples the rate. What is the overall order of the reaction?', 3, 0, '', '<p>Rate &prop; [A]<sup>1</sup> since 2<sup>1</sup> = 2. Rate &prop; [B]<sup>2</sup> since 2<sup>2</sup> = 4.</p><p>Overall order = 1 + 2 = <b>3</b>.</p>', '', () => 1 + 2);
nat(2, 'second order half-life', 'A second order reaction (one reactant) has k = 0.50 L mol<sup>-1</sup> s<sup>-1</sup> and [A]<sub>0</sub> = 0.20 M. Find t<sub>1/2</sub> in seconds.', 10, 0, 's', '<p>For second order t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>) = 1/(0.50 &times; 0.20) = <b>10 s</b>.</p>', '', () => 1 / (0.5 * 0.2));
nat(2, 'activation energy from Arrhenius plot', 'The slope of a plot of ln k versus 1/T is -6000 K. Find the activation energy in kJ/mol (R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup>).', 49.9, 0.2, 'kJ/mol', '<p>Slope = -E<sub>a</sub>/R, so E<sub>a</sub> = 6000 &times; 8.314 = 49884 J = <b>49.9 kJ/mol</b>.</p>', 'The slope is -E<sub>a</sub>/R for ln k; for log<sub>10</sub> k it is -E<sub>a</sub>/2.303R.', () => 6000 * 8.314 / 1000);
nat(2, 'effect of concentration on rate', 'The rate law is rate = k[A]<sup>2</sup>. By what factor does the rate change if [A] is tripled?', 9, 0, '', '<p>Rate &prop; [A]<sup>2</sup>, so tripling [A] multiplies the rate by 3<sup>2</sup> = <b>9</b>.</p>', '', () => 9);
nat(2, 'effect of volume on rate', 'For the gas phase reaction 2A + B &rarr; products with rate = k[A]<sup>2</sup>[B], the volume of the container is suddenly halved. By what factor does the rate change?', 8, 0, '', '<p>Halving the volume doubles every concentration. Rate &prop; [A]<sup>2</sup>[B]: 2<sup>2</sup> &times; 2 = <b>8</b>.</p>', 'Both concentrations double, not just one.', () => 2 ** 3);
mk(2, 'graphs of first order', 'For a first order reaction A &rarr; products, a straight line is obtained by plotting', 'ln[A] against t, with slope -k', ['[A] against t, with slope -k', '1/[A] against t, with slope k', 'ln[A] against 1/t, with slope k'], '<p>First order: ln[A] = ln[A]<sub>0</sub> - kt, a straight line with slope -k. A plot of [A] against t is a decaying curve; 1/[A] against t is the straight line for second order.</p>');
mk(2, 'graphs of second order', 'For a second order reaction (rate = k[A]<sup>2</sup>), the straight-line plot is', '1/[A] against t, with positive slope k', ['ln[A] against t', '[A] against t', '1/[A]<sup>2</sup> against t'], '<p>Integrated second order law: 1/[A] = 1/[A]<sub>0</sub> + kt. So 1/[A] rises linearly with t, and the slope is +k.</p>');
mk(2, 'graphs of zero order', 'For a zero order reaction, the concentration of reactant plotted against time gives', 'a straight line with negative slope equal to -k', ['an exponential decay curve', 'a horizontal line', 'a hyperbola'], '<p>Zero order: [A] = [A]<sub>0</sub> - kt, which is a straight line with slope -k. It runs out of reactant in time [A]<sub>0</sub>/k.</p>');
nat(2, 'radioactive decay', 'A radioactive sample of 64 g has a half-life of 6 h. What mass remains after 24 h?', 4, 0, 'g', '<p>24 h = 4 half-lives. Mass = 64 &times; (1/2)<sup>4</sup> = 64/16 = <b>4 g</b>.</p>', '', () => 64 / 16);
mk(2, 'molecularity and order', 'For an elementary reaction step, which statement is correct?', 'The order equals the molecularity', ['The order is always zero', 'The order is always one more than the molecularity', 'Molecularity can be fractional but order cannot'], '<p>An elementary step happens exactly as written, so its rate law follows from its coefficients: a bimolecular step 2A &rarr; P is second order. For a complex reaction the order is found by experiment and can differ from molecularity.</p>');
mk(2, 'pseudo first order', 'The acid-catalysed hydrolysis of ethyl acetate in a large excess of water is called pseudo first order because', 'the concentration of water hardly changes, so it appears in the rate constant', ['the reaction has only one product', 'water is a catalyst', 'ethyl acetate decomposes by itself'], '<p>CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> + H<sub>2</sub>O &rarr; CH<sub>3</sub>COOH + C<sub>2</sub>H<sub>5</sub>OH is really first order in ester and first order in water. Water is about 55 M and its change is negligible, so rate = k&prime;[ester] with k&prime; = k[H<sub>2</sub>O].</p>');
nat(2, 'activation energy', 'The rate constant of a reaction doubles when the temperature rises from 300 K to 310 K. Find E<sub>a</sub> in kJ/mol. (R = 8.314, log 2 = 0.301)', 53.6, 0.3, 'kJ/mol', '<p>log(k<sub>2</sub>/k<sub>1</sub>) = (E<sub>a</sub>/2.303R)(1/T<sub>1</sub> - 1/T<sub>2</sub>).</p><p>E<sub>a</sub> = 2.303 &times; 8.314 &times; 0.301 &times; (300 &times; 310/10) = 5.763 &times; 9300 = 53600 J = <b>53.6 kJ/mol</b>.</p>', '', () => 2.303 * 8.314 * 0.301 * 9300 / 1000);
nat(2, 'first order', 'For a first order reaction k = 0.0231 min<sup>-1</sup>. Find the half-life in minutes. (ln 2 = 0.693)', 30, 0, 'min', '<p>t<sub>1/2</sub> = 0.693/0.0231 = <b>30 min</b>.</p>', '', () => 0.693 / 0.0231);
mk(2, 'frequency factor', 'In k = A e<sup>-E<sub>a</sub>/RT</sup>, the factor A represents', 'the frequency of collisions with proper orientation (the pre-exponential factor)', ['the activation energy', 'the enthalpy of reaction', 'the temperature coefficient'], '<p>A is the pre-exponential or frequency factor. It is related to the collision frequency and the orientation (steric) requirement. The factor e<sup>-E<sub>a</sub>/RT</sup> is the fraction of collisions with energy at least E<sub>a</sub>.</p>');
mk(2, 'first order', 'The concentration of a reactant in a first order reaction falls from 0.80 M to 0.40 M in 20 min. In what further time will it fall to 0.10 M?', '40 min', ['20 min', '60 min', '80 min'], '<p>Half-life is 20 min. From 0.40 M to 0.10 M is two more halvings (0.40 &rarr; 0.20 &rarr; 0.10), so 2 &times; 20 = <b>40 min</b>.</p>', 'The question asks for the further time, not the total.');
mk(2, 'units of k', 'The unit of k for a second order reaction is', 'L mol<sup>-1</sup> s<sup>-1</sup>', ['mol L<sup>-1</sup> s<sup>-1</sup>', 's<sup>-1</sup>', 'L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>'], '<p>rate = k[A]<sup>2</sup>, so k = rate/[A]<sup>2</sup> = (mol L<sup>-1</sup> s<sup>-1</sup>)/(mol L<sup>-1</sup>)<sup>2</sup> = L mol<sup>-1</sup> s<sup>-1</sup>. In general, k has the unit (mol L<sup>-1</sup>)<sup>1-n</sup> s<sup>-1</sup>.</p>');
nat(2, 'second order integrated law', 'A second order reaction has [A]<sub>0</sub> = 0.50 M and k = 0.20 L mol<sup>-1</sup> s<sup>-1</sup>. Find [A] after 10 s in mol/L.', 0.25, 0.005, 'M', '<p>1/[A] = 1/[A]<sub>0</sub> + kt = 1/0.50 + 0.20 &times; 10 = 2 + 2 = 4 L/mol.</p><p>[A] = <b>0.25 M</b>.</p>', 'The answer is 1/[A], then invert.', () => 1 / (1 / 0.5 + 0.2 * 10));
nat(2, 'temperature coefficient', 'The rate of a reaction triples for every 10 K rise in temperature. By what factor does the rate increase for a 30 K rise?', 27, 0, '', '<p>Three steps of 10 K: 3 &times; 3 &times; 3 = 3<sup>3</sup> = <b>27</b>.</p>', 'The factors multiply; they do not add.', () => 3 ** 3);
mk(2, 'effect of catalyst', 'A catalyst has the same effect on the forward and reverse reactions because it', 'lowers the activation energy of both by the same amount', ['raises the energy of the products', 'changes &Delta;H of the reaction', 'is consumed in the forward step only'], '<p>A catalyst lowers the top of the energy barrier. Both forward and reverse reactions cross the same barrier, so both E<sub>a</sub> values fall by the same amount and the equilibrium constant stays the same.</p>');
mk(2, 'factors affecting rate', 'Which factor does NOT change the value of the rate constant k of a given reaction?', 'concentration of the reactants', ['temperature', 'presence of a catalyst', 'nature of the reaction'], '<p>k depends on temperature and on the nature of the reaction (A and E<sub>a</sub>), and changes with a catalyst. It does not depend on concentration: rate changes with concentration, k does not.</p>', 'Rate and rate constant are different things.');
nat(2, 'rate and stoichiometry', 'For N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub>, H<sub>2</sub> disappears at 0.60 mol L<sup>-1</sup> s<sup>-1</sup>. At what rate does NH<sub>3</sub> form (mol L<sup>-1</sup> s<sup>-1</sup>)?', 0.40, 0.01, 'mol L<sup>-1</sup> s<sup>-1</sup>', '<p>-(1/3) d[H<sub>2</sub>]/dt = (1/2) d[NH<sub>3</sub>]/dt.</p><p>d[NH<sub>3</sub>]/dt = (2/3) &times; 0.60 = <b>0.40</b>.</p>', 'Match the coefficients: 3 for H<sub>2</sub>, 2 for NH<sub>3</sub>.', () => 2 / 3 * 0.6);
mk(2, 'order of reaction', 'Which statement about the order of a reaction is correct?', 'It is found by experiment and may be zero, a fraction or a whole number', ['It is always the sum of the stoichiometric coefficients', 'It must be a whole number', 'It cannot be zero'], '<p>Order comes from the experimental rate law. For example, rate = k[A]<sup>1/2</sup> is possible, and zero order occurs for many surface catalysed reactions. The balanced equation does not decide it.</p>');
nat(2, 'unit conversion', 'The rate constant of a first order reaction is 0.060 min<sup>-1</sup>. Express it in units of 10<sup>-3</sup> s<sup>-1</sup>.', 1.0, 0.01, '&times; 10<sup>-3</sup> s<sup>-1</sup>', '<p>0.060 min<sup>-1</sup> = 0.060/60 s<sup>-1</sup> = 1.0 &times; 10<sup>-3</sup> s<sup>-1</sup>, so <b>1.0</b>.</p>', '', () => 0.06 / 60 / 1e-3);
// ---------- Level 3 ----------
nat(3, 'initial rate method', 'For A + B &rarr; products, initial rates were measured:<table><tr><th>[A] (M)</th><th>[B] (M)</th><th>rate (M s<sup>-1</sup>)</th></tr><tr><td>0.10</td><td>0.10</td><td>4.0 &times; 10<sup>-4</sup></td></tr><tr><td>0.20</td><td>0.10</td><td>8.0 &times; 10<sup>-4</sup></td></tr><tr><td>0.10</td><td>0.30</td><td>3.6 &times; 10<sup>-3</sup></td></tr></table>Find k (in L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>).', 0.4, 0.01, 'L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>', '<p>Rows 1 and 2: [A] doubles, rate doubles, so order in A is 1.</p><p>Rows 1 and 3: [B] triples, rate increases 9 times, so order in B is 2.</p><p>Rate = k[A][B]<sup>2</sup>. From row 1: k = 4.0 &times; 10<sup>-4</sup>/(0.10 &times; 0.10<sup>2</sup>) = <b>0.40</b>.</p>', 'Find each order first; B is second order.', () => 4e-4 / (0.1 * 0.01));
nat(3, 'order from half-life', 'For a single reactant, the half-life is 100 s when [A]<sub>0</sub> = 0.10 M and 50 s when [A]<sub>0</sub> = 0.20 M. What is the order of the reaction?', 2, 0, '', '<p>t<sub>1/2</sub> &prop; [A]<sub>0</sub><sup>1-n</sup>. Doubling [A]<sub>0</sub> halves t<sub>1/2</sub>: 2<sup>1-n</sup> = 1/2, so 1 - n = -1 and n = <b>2</b>.</p>', 'For first order t<sub>1/2</sub> does not change; for zero order it would double.', () => 2);
nat(3, 'first order', 'For a first order reaction, how many times the half-life does it take for 99 % completion? Give the ratio t<sub>99%</sub>/t<sub>1/2</sub> (log 100 = 2, ln 2 = 0.693).', 6.64, 0.05, '', '<p>t<sub>99%</sub> = (2.303/k) log 100 = 4.606/k. t<sub>1/2</sub> = 0.693/k.</p><p>Ratio = 4.606/0.693 = <b>6.64</b>.</p>', '', () => 2.303 * 2 / 0.693);
nat(3, 'first order', 'A first order reaction has t<sub>1/2</sub> = 20 min. How long (in minutes) does it take for 87.5 % of the reactant to react?', 60, 0, 'min', '<p>87.5 % reacted leaves 12.5 % = 1/8 = (1/2)<sup>3</sup>, three half-lives.</p><p>t = 3 &times; 20 = <b>60 min</b>.</p>', '', () => 3 * 20);
nat(3, 'gaseous first order', '2N<sub>2</sub>O<sub>5</sub>(g) &rarr; 4NO<sub>2</sub>(g) + O<sub>2</sub>(g) is first order. Starting with pure N<sub>2</sub>O<sub>5</sub> at 400 mmHg, the total pressure after 100 s is 520 mmHg. Find k in units of 10<sup>-3</sup> s<sup>-1</sup> (log 1.25 = 0.0969).', 2.23, 0.03, '&times; 10<sup>-3</sup> s<sup>-1</sup>', '<p>If N<sub>2</sub>O<sub>5</sub> loses 2p, NO<sub>2</sub> gains 4p and O<sub>2</sub> gains p, so the total rises by 3p.</p><p>3p = 120, p = 40. P(N<sub>2</sub>O<sub>5</sub>) = 400 - 80 = 320 mmHg.</p><p>k = (2.303/100) log(400/320) = 0.02303 &times; 0.0969 = <b>2.23 &times; 10<sup>-3</sup> s<sup>-1</sup></b>.</p>', 'Pressure change is 3p, but N<sub>2</sub>O<sub>5</sub> used is 2p.', () => 2.303 / 100 * 0.0969 / 1e-3);
nat(3, 'first order', 'A first order reaction goes from 0.50 M to 0.125 M in 30 min. Find the half-life in minutes.', 15, 0, 'min', '<p>0.50 &rarr; 0.125 is a factor of 4 = two half-lives, so t<sub>1/2</sub> = 30/2 = <b>15 min</b>.</p>', '', () => 30 / 2);
nat(3, 'Arrhenius equation', 'A reaction has E<sub>a</sub> = 50 kJ/mol. By what factor does the rate constant increase when the temperature goes from 300 K to 310 K? (R = 8.314)', 1.91, 0.02, '', '<p>ln(k<sub>2</sub>/k<sub>1</sub>) = (E<sub>a</sub>/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (50000/8.314)(1/300 - 1/310) = 6014 &times; 1.075 &times; 10<sup>-4</sup> = 0.6467.</p><p>k<sub>2</sub>/k<sub>1</sub> = e<sup>0.6467</sup> = <b>1.91</b>.</p>', 'With E<sub>a</sub> = 50 kJ the factor is below 2 even though 10 K is added.', () => Math.exp(50000 / 8.314 * (1 / 300 - 1 / 310)));
nat(3, 'Arrhenius equation', 'The rate constant of a reaction becomes 4 times when the temperature rises from 300 K to 320 K. Find E<sub>a</sub> in kJ/mol. (R = 8.314, log 4 = 0.602)', 55.3, 0.4, 'kJ/mol', '<p>E<sub>a</sub> = 2.303 R log(k<sub>2</sub>/k<sub>1</sub>) T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = 2.303 &times; 8.314 &times; 0.602 &times; (300 &times; 320/20).</p><p>= 11.53 &times; 4800 = 55300 J = <b>55.3 kJ/mol</b>.</p>', '', () => 2.303 * 8.314 * 0.602 * 4800 / 1000);
nat(3, 'second order', 'A second order reaction (single reactant) has k = 0.010 L mol<sup>-1</sup> s<sup>-1</sup> and [A]<sub>0</sub> = 0.50 M. How long (s) does it take for 75 % to react?', 600, 0, 's', '<p>t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>) = 1/(0.010 &times; 0.50) = 200 s.</p><p>For second order, t<sub>75%</sub> = 3 t<sub>1/2</sub> (1/[A] goes from 2 to 8, a rise of 6 = 3 &times; 2). So t = <b>600 s</b>.</p>', 'For first order it would be 2 half-lives; for second order it is 3.', () => 3 * 200);
nat(3, 'zero order', 'A zero order reaction has rate 0.010 mol L<sup>-1</sup> s<sup>-1</sup>. How long does it take for the concentration to fall by 0.30 mol/L?', 30, 0, 's', '<p>Constant rate means x = kt, so t = 0.30/0.010 = <b>30 s</b>.</p>', '', () => 0.30 / 0.010);
nat(3, 'effect of catalyst', 'A catalyst lowers E<sub>a</sub> from 75 kJ/mol to 50 kJ/mol at 300 K, with no change in A. Find log<sub>10</sub> of the factor by which k increases (R = 8.314).', 4.35, 0.03, '', '<p>k<sub>cat</sub>/k = e<sup>&Delta;E<sub>a</sub>/RT</sup>, so log(k<sub>cat</sub>/k) = &Delta;E<sub>a</sub>/(2.303RT) = 25000/(2.303 &times; 8.314 &times; 300) = <b>4.35</b>, a factor of about 2 &times; 10<sup>4</sup>.</p>', '', () => 25000 / (2.303 * 8.314 * 300));
nat(3, 'radiocarbon dating', 'A wooden sample has one quarter of the <sup>14</sup>C activity of living wood. Find its age in years (half-life of <sup>14</sup>C = 5730 y).', 11460, 0, 'years', '<p>One quarter remaining = (1/2)<sup>2</sup>, two half-lives.</p><p>Age = 2 &times; 5730 = <b>11460 y</b>.</p>', '', () => 2 * 5730);
nat(3, 'parallel reactions', 'A reactant A forms B (k<sub>1</sub> = 3.0 &times; 10<sup>-3</sup> s<sup>-1</sup>) and C (k<sub>2</sub> = 1.0 &times; 10<sup>-3</sup> s<sup>-1</sup>) by two parallel first order paths. What percentage of the A reacted ends up as B?', 75, 0, '%', '<p>The products form in the ratio of the rate constants: [B]/[C] = k<sub>1</sub>/k<sub>2</sub> = 3.</p><p>Fraction B = k<sub>1</sub>/(k<sub>1</sub> + k<sub>2</sub>) = 3/4 = <b>75 %</b>.</p>', '', () => 3 / 4 * 100);
nat(3, 'energy profile', 'In a reaction, E<sub>a</sub>(forward) = 80 kJ/mol and E<sub>a</sub>(reverse) = 120 kJ/mol. What is &Delta;H of the forward reaction in kJ/mol?', -40, 0, 'kJ/mol', '<p>&Delta;H = E<sub>a</sub>(forward) - E<sub>a</sub>(reverse) = 80 - 120 = <b>-40 kJ/mol</b> (exothermic).</p>', 'It is forward minus reverse, not the other way round.', () => 80 - 120);
mk(3, 'unit trap', 'The rate of a reaction is 4.0 &times; 10<sup>-3</sup> mol L<sup>-1</sup> s<sup>-1</sup> when [A] = 0.20 M and the reaction is first order in A. The rate constant is', '2.0 &times; 10<sup>-2</sup> s<sup>-1</sup>', ['2.0 &times; 10<sup>-2</sup> L mol<sup>-1</sup> s<sup>-1</sup>', '8.0 &times; 10<sup>-4</sup> s<sup>-1</sup>', '2.0 &times; 10<sup>-2</sup> mol L<sup>-1</sup> s<sup>-1</sup>'], '<p>k = rate/[A] = 4.0 &times; 10<sup>-3</sup>/0.20 = 2.0 &times; 10<sup>-2</sup>, with unit s<sup>-1</sup> for a first order reaction. The numeric value alone is not enough; the unit matters too.</p>', 'The first and last options have the right number but the wrong unit.');
mk(3, 'order from stoichiometry', 'For 2NO + O<sub>2</sub> &rarr; 2NO<sub>2</sub>, the experimental rate law is rate = k[NO]<sup>2</sup>[O<sub>2</sub>]. Which statement is correct?', 'The order is 3, and it matches the sum of the coefficients by coincidence of the mechanism', ['The order must be 3 because 2 + 1 = 3 always holds', 'The order is 2 because NO is squared', 'The reaction is bimolecular'], '<p>Order = 2 + 1 = 3 from the rate law. In this case it equals the sum of the stoichiometric coefficients (3), but that is not a rule: for 2N<sub>2</sub>O<sub>5</sub> &rarr; 4NO<sub>2</sub> + O<sub>2</sub> the order is 1, not 2.</p>');
mk(3, 'mechanism and rate law', 'A reaction occurs in two steps: (1) H<sub>2</sub>O<sub>2</sub> + I<sup>-</sup> &rarr; H<sub>2</sub>O + IO<sup>-</sup> (slow); (2) H<sub>2</sub>O<sub>2</sub> + IO<sup>-</sup> &rarr; H<sub>2</sub>O + O<sub>2</sub> + I<sup>-</sup> (fast). The rate law is', 'rate = k[H<sub>2</sub>O<sub>2</sub>][I<sup>-</sup>]', ['rate = k[H<sub>2</sub>O<sub>2</sub>]<sup>2</sup>[I<sup>-</sup>]', 'rate = k[H<sub>2</sub>O<sub>2</sub>][IO<sup>-</sup>]', 'rate = k[H<sub>2</sub>O<sub>2</sub>]'], '<p>The rate is set by the slow step 1, which is bimolecular: rate = k[H<sub>2</sub>O<sub>2</sub>][I<sup>-</sup>]. IO<sup>-</sup> is an intermediate and cannot appear in the final rate law. I<sup>-</sup> is a catalyst: used in step 1, regenerated in step 2.</p>');
mk(3, 'fast equilibrium step', 'For 2NO + O<sub>2</sub> &rarr; 2NO<sub>2</sub> the proposed mechanism is: (1) 2NO &rightleftharpoons; N<sub>2</sub>O<sub>2</sub> (fast, equilibrium); (2) N<sub>2</sub>O<sub>2</sub> + O<sub>2</sub> &rarr; 2NO<sub>2</sub> (slow). The rate law is', 'rate = k[NO]<sup>2</sup>[O<sub>2</sub>]', ['rate = k[N<sub>2</sub>O<sub>2</sub>][O<sub>2</sub>] and N<sub>2</sub>O<sub>2</sub> is kept in the final law', 'rate = k[NO][O<sub>2</sub>]', 'rate = k[NO]<sup>2</sup>'], '<p>Slow step: rate = k<sub>2</sub>[N<sub>2</sub>O<sub>2</sub>][O<sub>2</sub>]. The intermediate comes from the fast equilibrium: [N<sub>2</sub>O<sub>2</sub>] = K[NO]<sup>2</sup>.</p><p>So rate = k<sub>2</sub>K[NO]<sup>2</sup>[O<sub>2</sub>], third order overall.</p>', 'Replace an intermediate with the reactants that make it.');
mk(3, 'collision theory', 'The steric factor in collision theory accounts for', 'the fact that only collisions with the right orientation are effective', ['the energy of the collision', 'the catalyst used', 'the volume of the container'], '<p>Even when molecules collide with enough energy, they react only if oriented correctly. The steric (probability) factor P &lt; 1 puts this in the rate equation: k = P Z e<sup>-E<sub>a</sub>/RT</sup>.</p>');
mk(3, 'Arrhenius plot', 'A plot of ln k versus 1/T is a straight line. Its intercept on the ln k axis is', 'ln A', ['-E<sub>a</sub>/R', 'E<sub>a</sub>', 'ln(E<sub>a</sub>/R)'], '<p>ln k = ln A - E<sub>a</sub>/(RT). With ln k on y and 1/T on x, the intercept is ln A and the slope is -E<sub>a</sub>/R.</p>');
mk(3, 'half-life and concentration', 'Which of these reactions has a half-life independent of the initial concentration?', 'first order', ['zero order', 'second order (one reactant)', 'third order'], '<p>First order: t<sub>1/2</sub> = 0.693/k. Zero order: [A]<sub>0</sub>/2k (proportional to [A]<sub>0</sub>). Second order: 1/(k[A]<sub>0</sub>) (inversely proportional).</p>');
mk(3, 'energy diagram', 'On the potential energy diagram of a reaction, the difference in energy between the reactants and the top of the barrier is', 'the activation energy of the forward reaction', ['the enthalpy of reaction', 'the activation energy of the reverse reaction', 'the threshold energy minus the activation energy'], '<p>Reactants up to the peak: E<sub>a</sub> (forward). Products to the peak: E<sub>a</sub> (reverse). Reactants to products: &Delta;H.</p>');
mk(3, 'zero order catalysis', 'The decomposition of NH<sub>3</sub> on a hot platinum surface is zero order at high pressure because', 'the catalyst surface is saturated, so the rate no longer depends on pressure', ['ammonia does not react at high pressure', 'platinum is consumed during the reaction', 'the reaction has molecularity zero'], '<p>At high pressure every active site is occupied. Adding more NH<sub>3</sub> cannot raise the rate, which is therefore constant (zero order). Molecularity can never be zero, so option 4 is wrong.</p>');
mk(3, 'effect of temperature', 'When the temperature is raised, the rate of a reaction increases mainly because', 'a larger fraction of molecules has energy at least equal to the activation energy', ['the activation energy decreases', 'the collision frequency increases greatly', 'the orientation of molecules improves'], '<p>The collision frequency rises only by a small amount (about the square root of T). The big change is in the fraction with E &ge; E<sub>a</sub>, which varies as e<sup>-E<sub>a</sub>/RT</sup>. E<sub>a</sub> itself is nearly constant.</p>', 'A rise in collision frequency is real but small.');
mk(3, 'order from half-lives', 'The half-life of a reaction is doubled when its initial concentration is doubled. The reaction is of', 'zero order', ['first order', 'second order', 'third order'], '<p>t<sub>1/2</sub> &prop; [A]<sub>0</sub><sup>1-n</sup>. If t<sub>1/2</sub> &prop; [A]<sub>0</sub><sup>1</sup>, then 1 - n = 1 and n = 0.</p>');
mk(3, 'pseudo first order', 'A reaction A + B &rarr; products has rate = k[A][B]. If B is present in very large excess, the reaction behaves as', 'first order in A, with rate constant k[B]<sub>0</sub>', ['zero order', 'second order in A', 'first order with rate constant k'], '<p>[B] stays almost constant, so rate = (k[B]<sub>0</sub>)[A] = k&prime;[A]. It looks first order in A with k&prime; = k[B]<sub>0</sub>, not k.</p>');
mk(3, 'half-life of radioactive isotopes', 'The half-life of a radioactive isotope', 'does not depend on temperature or pressure', ['doubles if the temperature is raised 10 K', 'depends on the chemical compound it is in', 'decreases as the sample size increases'], '<p>Nuclear decay is a property of the nucleus. Temperature, pressure and chemical combination do not change it, and as a first order process its half-life is independent of the amount of sample.</p>');
mk(3, 'intermediate', 'In a reaction mechanism, a species formed in one step and consumed in a later step is called', 'an intermediate', ['a catalyst', 'a reactant', 'an activated complex'], '<p>An intermediate is created and used up within the mechanism and does not appear in the overall equation. A catalyst is used up and then regenerated, but it is present at the start. The activated complex is the unstable arrangement at the energy maximum, not a species that can be isolated.</p>');
mk(3, 'units of k', 'If k has the unit L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>, the order of the reaction is', '3', ['1', '2', '4'], '<p>The unit of k is (mol L<sup>-1</sup>)<sup>1-n</sup> s<sup>-1</sup> = L<sup>n-1</sup> mol<sup>1-n</sup> s<sup>-1</sup>. For L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>, n - 1 = 2, so n = 3.</p>');
// ---------- Level 4 ----------
nat(4, 'gaseous first order', 'A(g) &rarr; B(g) + C(g) is first order. Starting with pure A at 100 mmHg, the total pressure after 20 min is 150 mmHg. Find k in units of 10<sup>-3</sup> min<sup>-1</sup> (log 2 = 0.301).', 34.7, 0.4, '&times; 10<sup>-3</sup> min<sup>-1</sup>', '<p>If p of A reacts, the total pressure is P<sub>0</sub> + p. So p = 50 and P(A) = 100 - 50 = 50 mmHg.</p><p>k = (2.303/20) log(100/50) = 0.11515 &times; 0.301 = <b>34.7 &times; 10<sup>-3</sup> min<sup>-1</sup></b>.</p>', 'Total pressure is not the pressure of A.', () => 2.303 / 20 * 0.301 / 1e-3);
nat(4, 'consecutive reactions', 'In A &rarr; B &rarr; C (both first order), k<sub>1</sub> = 0.20 min<sup>-1</sup> and k<sub>2</sub> = 0.10 min<sup>-1</sup>. The concentration of B is maximum at t<sub>max</sub> = ln(k<sub>1</sub>/k<sub>2</sub>)/(k<sub>1</sub> - k<sub>2</sub>). Find t<sub>max</sub> in minutes (ln 2 = 0.693).', 6.93, 0.05, 'min', '<p>t<sub>max</sub> = ln(0.20/0.10)/(0.20 - 0.10) = 0.693/0.10 = <b>6.93 min</b>.</p><p>Early on, B forms faster than it is used up, so [B] rises; later the loss of B wins and [B] falls.</p>', '', () => 0.693 / 0.1);
nat(4, 'Arrhenius equation', 'A reaction has A = 1.0 &times; 10<sup>13</sup> s<sup>-1</sup> and E<sub>a</sub> = 100 kJ/mol. Find k at 300 K in units of 10<sup>-5</sup> s<sup>-1</sup> (R = 8.314).', 3.87, 0.1, '&times; 10<sup>-5</sup> s<sup>-1</sup>', '<p>E<sub>a</sub>/RT = 100000/(8.314 &times; 300) = 40.09.</p><p>e<sup>-40.09</sup> = 10<sup>-17.41</sup> = 3.87 &times; 10<sup>-18</sup>.</p><p>k = 1.0 &times; 10<sup>13</sup> &times; 3.87 &times; 10<sup>-18</sup> = <b>3.87 &times; 10<sup>-5</sup> s<sup>-1</sup></b>.</p>', 'Use joules (100000) with R in J.', () => 1e13 * Math.exp(-100000 / (8.314 * 300)) / 1e-5);
nat(4, 'parallel reactions', 'A decomposes by two parallel first order paths with k<sub>1</sub> = 0.040 min<sup>-1</sup> and k<sub>2</sub> = 0.010 min<sup>-1</sup>. Find the half-life of A in minutes (ln 2 = 0.693).', 13.9, 0.1, 'min', '<p>For parallel paths the overall rate constant is the sum: k = 0.040 + 0.010 = 0.050 min<sup>-1</sup>.</p><p>t<sub>1/2</sub> = 0.693/0.050 = <b>13.9 min</b>.</p>', 'Add the rate constants; do not average.', () => 0.693 / 0.05);
nat(4, 'pseudo first order', 'Ethyl acetate hydrolyses in dilute acid with pseudo first order rate constant k&prime; = 2.0 &times; 10<sup>-5</sup> s<sup>-1</sup>. Find the half-life in hours (ln 2 = 0.693).', 9.63, 0.1, 'h', '<p>t<sub>1/2</sub> = 0.693/k&prime; = 0.693/(2.0 &times; 10<sup>-5</sup>) = 34650 s.</p><p>In hours: 34650/3600 = <b>9.63 h</b>.</p>', '', () => 0.693 / 2e-5 / 3600);
nat(4, 'first order', 'For a first order reaction, how many half-lives are needed for 99.9 % completion? (log 1000 = 3, ln 2 = 0.693)', 9.97, 0.05, '', '<p>t = (2.303/k) log 1000 = 6.909/k, and t<sub>1/2</sub> = 0.693/k.</p><p>t/t<sub>1/2</sub> = 6.909/0.693 = <b>9.97</b>, close to 10, since (1/2)<sup>10</sup> &asymp; 0.001.</p>', '', () => 2.303 * 3 / 0.693);
nat(4, 'radioactive decay', 'Isotopes X (t<sub>1/2</sub> = 10 days) and Y (t<sub>1/2</sub> = 20 days) start with equal numbers of atoms. Find N<sub>X</sub>/N<sub>Y</sub> after 40 days.', 0.25, 0.01, '', '<p>X: 40/10 = 4 half-lives, so (1/2)<sup>4</sup> = 1/16 left. Y: 40/20 = 2 half-lives, so (1/2)<sup>2</sup> = 1/4 left.</p><p>N<sub>X</sub>/N<sub>Y</sub> = (1/16)/(1/4) = <b>0.25</b>.</p>', '', () => (1 / 16) / (1 / 4));
nat(4, 'activation energy from half-lives', 'The half-life of a first order reaction is 80 s at 300 K and 10 s at 330 K. Find E<sub>a</sub> in kJ/mol (R = 8.314, log 8 = 0.903).', 57.1, 0.4, 'kJ/mol', '<p>k &prop; 1/t<sub>1/2</sub>, so k<sub>2</sub>/k<sub>1</sub> = 80/10 = 8.</p><p>E<sub>a</sub> = 2.303 R log 8 &times; T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = 2.303 &times; 8.314 &times; 0.903 &times; (300 &times; 330/30) = 17.29 &times; 3300 = <b>57.1 kJ/mol</b>.</p>', 'A shorter half-life means a larger k, so the ratio is t<sub>1</sub>/t<sub>2</sub>.', () => 2.303 * 8.314 * 0.903 * 3300 / 1000);
nat(4, 'pseudo first order', 'The reaction A + B &rarr; products, rate = k[A][B], is studied with [A]<sub>0</sub> = 1.0 &times; 10<sup>-3</sup> M and [B]<sub>0</sub> = 1.0 M. The observed half-life of A is 25 s. Find k in L mol<sup>-1</sup> s<sup>-1</sup> (ln 2 = 0.693).', 0.0277, 0.0005, 'L mol<sup>-1</sup> s<sup>-1</sup>', '<p>B is in 1000-fold excess, so k&prime; = k[B]<sub>0</sub> = 0.693/25 = 0.02772 s<sup>-1</sup>.</p><p>k = k&prime;/[B]<sub>0</sub> = 0.02772/1.0 = <b>0.0277 L mol<sup>-1</sup> s<sup>-1</sup></b>.</p>', '', () => 0.693 / 25 / 1.0);
nat(4, 'Arrhenius equation', 'The rate of a reaction triples when the temperature rises from 300 K to 310 K. Find E<sub>a</sub> in kJ/mol (R = 8.314, log 3 = 0.477).', 84.9, 0.5, 'kJ/mol', '<p>E<sub>a</sub> = 2.303 R log 3 &times; T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = 2.303 &times; 8.314 &times; 0.477 &times; 9300 = 9.133 &times; 9300 = 84900 J = <b>84.9 kJ/mol</b>.</p>', '', () => 2.303 * 8.314 * 0.477 * 9300 / 1000);
mk(4, 'half-life graphs', 'The plot of half-life against initial concentration [A]<sub>0</sub> is a straight line through the origin for', 'a zero order reaction', ['a first order reaction', 'a second order reaction', 'any reaction of fractional order'], '<p>Zero order: t<sub>1/2</sub> = [A]<sub>0</sub>/2k, a straight line through the origin. First order: a horizontal line. Second order: t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>), a hyperbola.</p>');
mk(4, 'rate vs time', 'In a first order reaction, the slope of the [A] versus t curve at any instant', 'is -k[A] and decreases as the reaction proceeds', ['is -k and remains constant', 'is -k[A]<sup>2</sup> and increases', 'is zero at all times'], '<p>Rate = -d[A]/dt = k[A]. As [A] falls, the slope gets flatter, so the curve decays exponentially. Constant slope would be zero order.</p>');
mk(4, 'effect of temperature on K', 'For an exothermic reversible reaction, raising the temperature', 'increases both k<sub>f</sub> and k<sub>r</sub>, with k<sub>r</sub> increasing more, so K decreases', ['increases k<sub>f</sub> only', 'decreases both k<sub>f</sub> and k<sub>r</sub>', 'increases both equally so K is unchanged'], '<p>Both rate constants rise with T (Arrhenius). For an exothermic reaction E<sub>a</sub>(reverse) &gt; E<sub>a</sub>(forward), so k<sub>r</sub> is more sensitive to T. K = k<sub>f</sub>/k<sub>r</sub> therefore falls, matching Le Chatelier.</p>', 'Both k values go up; K can still fall.');
mk(4, 'activation energy and sensitivity', 'Two reactions have the same A. Reaction X has E<sub>a</sub> = 40 kJ/mol and Y has 80 kJ/mol. At 300 K, as temperature is raised, the rate constant', 'of Y increases more rapidly, but is still smaller than that of X at 300 K', ['of X increases more rapidly and is larger than Y', 'of both increases equally', 'of Y is larger than that of X at 300 K'], '<p>k = A e<sup>-E<sub>a</sub>/RT</sup>: with equal A, smaller E<sub>a</sub> gives a larger k at a given T, so k(X) &gt; k(Y). The higher the E<sub>a</sub>, the steeper the rise of ln k with T, so Y is more temperature-sensitive.</p>');
mk(4, 'catalyst and mechanism', 'A catalyst', 'takes part in the mechanism and is regenerated, giving a new path of lower E<sub>a</sub>', ['changes &Delta;G of the reaction', 'is consumed, so its mass must decrease', 'increases the yield of products at equilibrium'], '<p>A catalyst is used in one step and regenerated in another. It speeds up both directions, so equilibrium is reached sooner but the position of equilibrium and &Delta;G (and &Delta;H) are unchanged.</p>');
mk(4, 'integrated rate laws', 'A reaction is 50 % complete in 40 min and 75 % complete in 60 min. Its order is', 'zero', ['first', 'second', 'third'], '<p>Test each order against the data. Zero order: t<sub>1/2</sub> = 40 min means the reaction ends at 80 min, so at 60 min (3/4 of the way) it is 75 % done. This fits. First order would need 80 min for 75 %; second order would need 120 min. So the order is <b>zero</b>.</p>', 'Check which order gives 75 % at 60 min, not just 50 % at 40 min.');
mk(4, 'dependence of k', 'Rate constant k of a reaction is 2 &times; 10<sup>-3</sup> s<sup>-1</sup> at 300 K and 8 &times; 10<sup>-3</sup> s<sup>-1</sup> at 320 K. A plot of log k versus 1/T has a slope of about', '-2890 K', ['-1255 K', '+2890 K', '-6654 K'], '<p>Slope = -E<sub>a</sub>/(2.303R) = -log(k<sub>2</sub>/k<sub>1</sub>) &times; T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = -0.602 &times; 4800 = <b>-2890 K</b>. The value -6654 K would be the slope of ln k against 1/T (-E<sub>a</sub>/R).</p>', 'log versus ln changes the slope by 2.303.');
mk(4, 'molecularity trap', 'Which statement about a reaction with rate = k[A][B] is correct?', 'The reaction is second order; its molecularity may not be two if the mechanism has several steps', ['The reaction is always bimolecular', 'The reaction has an order of 1', 'The reaction must be elementary'], '<p>Order = 1 + 1 = 2. But rate laws are found by experiment, and a complex reaction can show second order while the actual steps have different molecularity.</p>');
// ---------- Level 5 ----------
nat(5, 'opposing reactions', 'A &rightleftharpoons; B with first order rate constants k<sub>f</sub> = 0.030 min<sup>-1</sup> (forward) and k<sub>r</sub> = 0.010 min<sup>-1</sup> (reverse). Starting with pure A, the approach to equilibrium is first order with rate constant k<sub>f</sub> + k<sub>r</sub>. Find the time (min) for the distance from equilibrium to halve (ln 2 = 0.693).', 17.3, 0.1, 'min', '<p>The deviation from equilibrium decays with k = k<sub>f</sub> + k<sub>r</sub> = 0.040 min<sup>-1</sup>.</p><p>t<sub>1/2</sub> = 0.693/0.040 = <b>17.3 min</b>. (The equilibrium constant is K = k<sub>f</sub>/k<sub>r</sub> = 3.)</p>', 'The relaxation uses the sum of both constants.', () => 0.693 / 0.04);
nat(5, 'competing reactions', 'Two parallel reactions of the same reactant have the same A. Their activation energies are 60 and 80 kJ/mol. Find k<sub>1</sub>/k<sub>2</sub> at 600 K (R = 8.314).', 55.1, 0.6, '', '<p>k<sub>1</sub>/k<sub>2</sub> = e<sup>-(60000 - 80000)/(RT)</sup> = e<sup>20000/(8.314 &times; 600)</sup> = e<sup>4.009</sup> = <b>55.1</b>.</p><p>At lower temperatures the ratio is larger: selectivity improves at lower T.</p>', '', () => Math.exp(20000 / (8.314 * 600)));
nat(5, 'integrated first order and mixing', 'A first order reaction A &rarr; B has t<sub>1/2</sub> = 40 min. Starting with 1.0 mol of A, how many moles of B have formed after 2 hours?', 0.875, 0.005, 'mol', '<p>2 h = 120 min = 3 half-lives. A left = (1/2)<sup>3</sup> = 0.125 mol.</p><p>B formed = 1.0 - 0.125 = <b>0.875 mol</b>.</p>', 'The question asks for product, not reactant left.', () => 1 - 0.125);
nat(5, 'initial rates with unequal stoichiometry', 'For 2A + B &rarr; C the rate is first order in A and second order in B. At [A] = 0.10 M and [B] = 0.10 M the rate is 1.0 &times; 10<sup>-4</sup> M s<sup>-1</sup>. Find the rate (in 10<sup>-4</sup> M s<sup>-1</sup>) when [A] = 0.20 M and [B] = 0.30 M.', 18, 0, '&times; 10<sup>-4</sup> M s<sup>-1</sup>', '<p>Rate &prop; [A][B]<sup>2</sup>. [A] doubles (&times;2); [B] triples, so &times;3<sup>2</sup> = 9.</p><p>Rate = 1.0 &times; 2 &times; 9 = <b>18 &times; 10<sup>-4</sup> M s<sup>-1</sup></b>.</p>', 'The coefficient 2 of A does not become an exponent.', () => 2 * 9);
nat(5, 'half-life and rate constant', 'A second order reaction 2A &rarr; P with rate = k[A]<sup>2</sup> (k = 0.020 L mol<sup>-1</sup> s<sup>-1</sup>) starts at [A]<sub>0</sub> = 1.0 M. Find the time (in s) for [A] to fall to 0.20 M.', 200, 0, 's', '<p>1/[A] = 1/[A]<sub>0</sub> + kt. 1/0.20 = 5, 1/1.0 = 1, so kt = 4.</p><p>t = 4/0.020 = <b>200 s</b>.</p>', '', () => (5 - 1) / 0.02);
nat(5, 'secular equilibrium', 'A parent isotope has t<sub>1/2</sub> = 1000 years and its daughter t<sub>1/2</sub> = 1 year. In secular equilibrium the activities are equal (&lambda;<sub>1</sub>N<sub>1</sub> = &lambda;<sub>2</sub>N<sub>2</sub>). Find the ratio N<sub>2</sub>/N<sub>1</sub> (daughter to parent atoms) in units of 10<sup>-3</sup>.', 1.0, 0.01, '&times; 10<sup>-3</sup>', '<p>&lambda; &prop; 1/t<sub>1/2</sub>. Equal activities: N<sub>2</sub>/N<sub>1</sub> = &lambda;<sub>1</sub>/&lambda;<sub>2</sub> = t<sub>1/2</sub>(2)/t<sub>1/2</sub>(1) = 1/1000 = <b>1.0 &times; 10<sup>-3</sup></b>.</p>', 'Short-lived daughter means few atoms.', () => 1 / 1000 / 1e-3);
nat(5, 'average life', 'The mean (average) life of a radioactive nucleus is 1/&lambda;. A sample has t<sub>1/2</sub> = 6.93 h. Find its mean life in hours (ln 2 = 0.693).', 10, 0, 'h', '<p>&lambda; = 0.693/6.93 = 0.100 h<sup>-1</sup>. Mean life = 1/&lambda; = <b>10 h</b>. Mean life is longer than half-life by a factor of 1/0.693 = 1.44.</p>', '', () => 1 / (0.693 / 6.93));
msq(3, 'first order', 'Which statements are correct for a first order reaction?', ['The half-life is independent of the initial concentration', 'A plot of ln[A] against t is a straight line', 'The unit of k is s<sup>-1</sup>', 'The value of k increases when the initial concentration is increased'], [0, 1, 2], '<p>A, B and C are standard first order results. D is false: k does not depend on concentration (only on temperature and catalyst); the rate does.</p>');
msq(3, 'zero order', 'Which statements are correct for a zero order reaction?', ['The half-life is proportional to the initial concentration', 'The rate does not depend on the reactant concentration', 'A plot of ln[A] against t is a straight line', 'The unit of k is mol L<sup>-1</sup> s<sup>-1</sup>'], [0, 1, 3], '<p>A: t<sub>1/2</sub> = [A]<sub>0</sub>/2k. B: rate = k. D: k has the unit of rate. C is the first order plot; for zero order [A] against t is the straight line.</p>');
msq(3, 'factors affecting k', 'Which of the following will increase the value of the rate constant of a reaction?', ['Raising the temperature', 'Adding a suitable catalyst', 'Increasing the concentration of a reactant', 'Choosing a path with lower activation energy'], [0, 1, 3], '<p>k = A e<sup>-E<sub>a</sub>/RT</sup>. A higher T, a lower E<sub>a</sub> (a catalyst does this) raise k. Concentration changes the rate but not k.</p>');
msq(4, 'pseudo first order', 'Which of these are examples of pseudo first order reactions?', ['Acid-catalysed hydrolysis of ethyl acetate in excess water', 'Inversion of cane sugar in dilute acid solution', 'Decomposition of N<sub>2</sub>O<sub>5</sub> in CCl<sub>4</sub>', 'A + B with [B] hundreds of times larger than [A]'], [0, 1, 3], '<p>A and B involve water in large excess (constant). D is the general case. N<sub>2</sub>O<sub>5</sub> decomposition is truly first order, since it involves only one reacting species.</p>');
msq(4, 'Arrhenius plot', 'For an Arrhenius plot, which statements are correct?', ['ln k against 1/T has slope -E<sub>a</sub>/R', 'log<sub>10</sub> k against 1/T has slope -E<sub>a</sub>/(2.303R)', 'The intercept of ln k against 1/T is ln A', 'The slope becomes more negative when a catalyst is added'], [0, 1, 2], '<p>A, B and C follow from ln k = ln A - E<sub>a</sub>/RT. A catalyst lowers E<sub>a</sub>, so the line becomes less steep (the slope is less negative): D is false.</p>');
msq(4, 'radioactive decay', 'Which statements about radioactive decay are correct?', ['It follows first order kinetics', 'Its half-life does not depend on temperature', 'The activity is proportional to the number of undecayed nuclei', 'The half-life depends on the initial amount'], [0, 1, 2], '<p>A, B and C are right. D is wrong: the half-life of a first order process is independent of the amount.</p>');
msq(4, 'catalysis', 'A catalyst', ['lowers the activation energy of both forward and reverse reactions', 'does not change &Delta;H', 'shifts the position of equilibrium', 'changes the rate constant'], [0, 1, 3], '<p>It lowers E<sub>a</sub> both ways (A), leaves &Delta;H unchanged (B), speeds the approach to equilibrium and changes k (D), but not the equilibrium position (C).</p>');
msq(5, 'molecularity', 'Which statements about molecularity are correct?', ['It is defined only for an elementary step', 'It is always a whole number', 'It can be zero for some zero order reactions', 'It always equals the order for an overall multi-step reaction'], [0, 1], '<p>A and B are correct. Molecularity is never zero (C) and for multi-step reactions the order can differ from any step\'s molecularity (D).</p>');

// ---------- Assertion-reason ----------
asr(2, 'order of reaction', 'The order of a reaction can be zero or fractional.', 'The order is found by experiment and need not match the stoichiometric coefficients.', 0, '<p>Both true and R explains A: since order is read from the rate law found by experiment, it can take any value, such as 0 or 1/2.</p>');
asr(3, 'molecularity', 'The molecularity of an elementary reaction can never be fractional.', 'Molecularity is the number of reacting molecules that collide in a single elementary step.', 0, '<p>You cannot have half a molecule colliding, so molecularity is a whole number (1, 2 or rarely 3). R states what molecularity means and explains A.</p>');
asr(3, 'half-life', 'The half-life of a first order reaction is independent of the initial concentration.', 'For a first order reaction t<sub>1/2</sub> = 0.693/k.', 0, '<p>Both true. The expression contains only k, so concentration drops out. R explains A.</p>');
asr(3, 'temperature effect', 'The rate of a reaction generally increases with temperature.', 'At a higher temperature a larger fraction of molecules has energy greater than or equal to the activation energy.', 0, '<p>Both true. The Boltzmann-type factor e<sup>-E<sub>a</sub>/RT</sup> rises rapidly with T, which explains why the rate increases.</p>');
asr(4, 'pseudo first order', 'The hydrolysis of ethyl acetate in dilute aqueous acid appears to be first order.', 'The concentration of water is very large and practically constant during the reaction.', 0, '<p>Both true, and R is the reason: rate = k[ester][H<sub>2</sub>O] reduces to k&prime;[ester] as [H<sub>2</sub>O] stays constant.</p>');
asr(3, 'catalyst', 'A catalyst increases the equilibrium yield of products.', 'A catalyst lowers the activation energy of the reaction.', 3, '<p>A is false: a catalyst speeds up both forward and reverse reactions equally, so the equilibrium composition is unchanged. R is true.</p>', 'Faster does not mean more product at equilibrium.');
asr(4, 'zero order', 'Many zero order reactions are surface-catalysed reactions.', 'At high concentration the catalyst surface is saturated, so the rate no longer depends on reactant concentration.', 0, '<p>Both true and R explains A: when all sites are occupied the rate is constant, which is zero order behaviour.</p>');
asr(2, 'units of k', 'The unit of the rate constant depends on the order of the reaction.', 'The rate constant is given by k = rate/[A]<sup>n</sup>.', 0, '<p>Both true. Rate has fixed units, so k must change its unit with n: k has (mol L<sup>-1</sup>)<sup>1-n</sup> s<sup>-1</sup>.</p>');
asr(4, 'activation energy', 'The activation energy for the forward and reverse reactions is the same.', 'A catalyst lowers the activation energy of both forward and reverse reactions.', 3, '<p>A is false: E<sub>a</sub>(forward) - E<sub>a</sub>(reverse) = &Delta;H, which is zero only for thermoneutral reactions. R is true.</p>');
asr(5, 'consecutive reactions', 'In A &rarr; B &rarr; C the concentration of B first increases and then decreases.', 'At the start B is formed by A and consumed more slowly, as there is little B to react.', 0, '<p>Both true and R explains A: early on the rate of formation (k<sub>1</sub>[A]) exceeds the rate of removal (k<sub>2</sub>[B]); later [A] is low and removal wins.</p>');

// ---------- Statement-based ----------
stm(2, 'rate with time', 'The rate of a reaction generally decreases with time.', 'The concentration of reactants falls as the reaction proceeds.', 0, '<p>Both correct, and II is the reason for I (except zero order, where the rate is constant).</p>');
stm(3, 'order and stoichiometry', 'The order of a reaction is always equal to the sum of the stoichiometric coefficients of the reactants.', 'The rate law is determined experimentally.', 2, '<p>Statement I is incorrect (e.g. 2N<sub>2</sub>O<sub>5</sub> &rarr; products is first order). Statement II is correct.</p>');
stm(3, 'first order half-life', 'For a first order reaction, 99.9 % completion takes about ten half-lives.', 'The half-life of a first order reaction doubles when the initial concentration is doubled.', 1, '<p>Statement I is correct ((1/2)<sup>10</sup> &asymp; 1/1000). Statement II is incorrect: for first order the half-life is independent of concentration.</p>');
stm(4, 'temperature and activation energy', 'Raising the temperature increases the fraction of molecules with energy at least equal to E<sub>a</sub>.', 'Raising the temperature lowers the activation energy of the reaction.', 1, '<p>Statement I is correct. Statement II is incorrect: E<sub>a</sub> is nearly independent of temperature; the rate rises because of the larger fraction of energetic molecules.</p>');
stm(3, 'units of k', 'The unit of the rate constant of a first order reaction is s<sup>-1</sup>.', 'The unit of the rate constant of a second order reaction is L mol<sup>-1</sup> s<sup>-1</sup>.', 0, '<p>Both correct: first order k = rate/[A] has s<sup>-1</sup>, second order k = rate/[A]<sup>2</sup> has L mol<sup>-1</sup> s<sup>-1</sup>.</p>');
stm(4, 'activation energy and temperature sensitivity', 'A reaction with a high activation energy is more sensitive to a change in temperature.', 'For the same A, a reaction with a high activation energy has a smaller rate constant at a given temperature.', 0, '<p>Both correct: k = A e<sup>-E<sub>a</sub>/RT</sup> is smaller for larger E<sub>a</sub>, and the slope of ln k against 1/T (-E<sub>a</sub>/R) is steeper, so a temperature change has a bigger effect.</p>');
stm(4, 'radioactive decay', 'The rate of radioactive decay depends on the temperature.', 'Radioactive decay follows first order kinetics.', 2, '<p>Statement I is incorrect: decay is a nuclear process and is unaffected by temperature. Statement II is correct.</p>');
stm(3, 'molecularity and order', 'An overall reaction that is second order must be bimolecular.', 'An elementary bimolecular step has a second order rate law.', 2, '<p>Statement I is incorrect: order is experimental and may arise from a multi-step mechanism. Statement II is correct for an elementary step.</p>');
L.push({ type: 'mcq', level: 4, format: 'statements', exams: EXM[4], sub: 'mixed statements', q: '<p>How many of the following statements are correct?</p><p>(i) The unit of k for a zero order reaction is mol L<sup>-1</sup> s<sup>-1</sup>.<br>(ii) The half-life of a second order reaction (one reactant) is independent of [A]<sub>0</sub>.<br>(iii) A catalyst lowers E<sub>a</sub> for both forward and reverse reactions.<br>(iv) Molecularity of an elementary reaction can be zero.</p>', options: ['Only one', 'Only two', 'Only three', 'All four'], answer: 1, sol: '<p>(i) correct. (ii) wrong: second order t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>). (iii) correct. (iv) wrong. So two are correct.</p>' });
L.push({ type: 'mcq', level: 5, format: 'statements', exams: EXM[5], sub: 'mixed statements', q: '<p>How many of the following statements are correct?</p><p>(i) For a first order reaction the time for 75 % completion is twice the half-life.<br>(ii) For a second order reaction (one reactant) the time for 75 % completion is three times the half-life.<br>(iii) For a zero order reaction the time for 75 % completion is 1.5 times the half-life.<br>(iv) For a first order reaction the time for 87.5 % completion is three half-lives.</p>', options: ['Only two', 'Only three', 'All four', 'Only one'], answer: 2, sol: '<p>(i) 75 % done leaves 1/4 = two half-lives: correct. (ii) 1/[A] rises from 1/[A]<sub>0</sub> to 4/[A]<sub>0</sub>, a rise of 3/[A]<sub>0</sub>, against 1/[A]<sub>0</sub> for the first half-life: correct. (iii) zero order: t<sub>1/2</sub> = [A]<sub>0</sub>/2k, t<sub>75%</sub> = 0.75[A]<sub>0</sub>/k = 1.5 t<sub>1/2</sub>: correct. (iv) 12.5 % left = 3 half-lives: correct. All four.</p>', trap: 'Time to 75 % differs by order.' });
// ---------- Match ----------
mat(2, 'units of k', 'm1', 'Match each order (List I) with the unit of its rate constant (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>Unit of k = (mol L<sup>-1</sup>)<sup>1-n</sup> s<sup>-1</sup>. n = 0: mol L<sup>-1</sup> s<sup>-1</sup> (p). n = 1: s<sup>-1</sup> (q). n = 2: L mol<sup>-1</sup> s<sup>-1</sup> (r). n = 3: L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup> (s).</p>');
mat(3, 'half-life expressions', 'm2', 'Match each order, for a single reactant (List I), with its half-life (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-r, C-q, D-s', 'A-s, B-q, C-r, D-p'], '<p>Zero order: [A]<sub>0</sub>/2k (p). First order: 0.693/k (q). Second order: 1/(k[A]<sub>0</sub>) (r). General nth order: t<sub>1/2</sub> &prop; [A]<sub>0</sub><sup>1-n</sup> (s).</p>');
mat(3, 'straight-line plots', 'm3', 'Match each plot (List I) with what it shows (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-s, C-p, D-q'], '<p>[A] against t, straight line: zero order (p). ln[A] against t: first order (q). 1/[A] against t: second order (r). ln k against 1/T: Arrhenius plot with slope -E<sub>a</sub>/R (s).</p>');
mat(4, 'collision theory', 'm4', 'Match each observation (List I) with its main reason (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>Raising T raises the fraction of molecules with E &ge; E<sub>a</sub> (p). A catalyst gives a path with lower E<sub>a</sub> (q). Many collisions fail because of wrong orientation: the steric factor (r). Higher concentration gives more collisions per second (s).</p>');

// ---------- Passages ----------
PN(3, 'order of reaction', 'p1', 'What is the order of the reaction with respect to A?', 2, 0, '', '<p>Experiments 1 and 2: [A] doubles with [B] fixed, rate rises from 2.0 &times; 10<sup>-3</sup> to 8.0 &times; 10<sup>-3</sup>, a factor of 4 = 2<sup>2</sup>. So the order in A is <b>2</b>.</p>', '', () => Math.log(8 / 2) / Math.log(2));
PN(3, 'rate constant', 'p1', 'Find k in L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup> (the order in B is 1).', 2.0, 0.05, 'L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>', '<p>Experiments 2 and 3: [B] triples, rate triples, so the order in B is 1. Rate = k[A]<sup>2</sup>[B].</p><p>k = 2.0 &times; 10<sup>-3</sup>/(0.10<sup>2</sup> &times; 0.10) = <b>2.0</b>.</p>', '', () => 2e-3 / (0.1 ** 2 * 0.1));
PN(4, 'rate prediction', 'p1', 'Find the rate (in 10<sup>-3</sup> M s<sup>-1</sup>) when [A] = 0.050 M and [B] = 0.40 M.', 2.0, 0.05, '&times; 10<sup>-3</sup> M s<sup>-1</sup>', '<p>Rate = k[A]<sup>2</sup>[B] = 2.0 &times; (0.050)<sup>2</sup> &times; 0.40 = 2.0 &times; 0.0025 &times; 0.40 = 2.0 &times; 10<sup>-3</sup> M s<sup>-1</sup>, so <b>2.0</b>.</p>', 'Square [A].', () => 2 * 0.05 ** 2 * 0.4 / 1e-3);
PN(3, 'half-life', 'p2', 'Find the half-life in minutes (ln 2 = 0.693).', 100, 0, 'min', '<p>t<sub>1/2</sub> = 0.693/k = 0.693/(6.93 &times; 10<sup>-3</sup>) = <b>100 min</b>.</p>', '', () => 0.693 / 6.93e-3);
PN(3, 'fraction remaining', 'p2', 'What percentage of N<sub>2</sub>O<sub>5</sub> remains after 300 min?', 12.5, 0.1, '%', '<p>300 min = 3 half-lives. Remaining = (1/2)<sup>3</sup> = <b>12.5 %</b>.</p>', '', () => 100 / 8);
PN(4, 'time for completion', 'p2', 'Find the time in minutes for 90 % of N<sub>2</sub>O<sub>5</sub> to decompose (log 10 = 1).', 332, 2, 'min', '<p>t = (2.303/k) log(100/10) = (2.303/6.93 &times; 10<sup>-3</sup>) &times; 1 = <b>332 min</b>.</p>', '', () => 2.303 / 6.93e-3);
PN(3, 'activation energy', 'p3', 'Find E<sub>a</sub> in kJ/mol (R = 8.314, log 4 = 0.602).', 55.3, 0.4, 'kJ/mol', '<p>E<sub>a</sub> = 2.303 R log(k<sub>2</sub>/k<sub>1</sub>) &times; T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = 2.303 &times; 8.314 &times; 0.602 &times; (300 &times; 320/20) = <b>55.3 kJ/mol</b>.</p>', '', () => 2.303 * 8.314 * 0.602 * 4800 / 1000);
PN(4, 'Arrhenius plot', 'p3', 'Find the slope of a plot of log<sub>10</sub> k against 1/T, in kelvin.', -2890, 20, 'K', '<p>Slope = -E<sub>a</sub>/(2.303R) = -0.602 &times; 4800 = <b>-2890 K</b>.</p>', 'log plot slope is -E<sub>a</sub>/2.303R.', () => -0.602 * 4800);
P(3, 'effect of catalyst', 'p3', 'A catalyst is added and the experiment repeated. The straight line of ln k against 1/T becomes', 'less steep, with the same intercept ln A if A is unchanged', ['steeper, with a larger intercept', 'unchanged, because k does not depend on E<sub>a</sub>', 'horizontal'], '<p>The slope is -E<sub>a</sub>/R. A catalyst lowers E<sub>a</sub>, so the slope is less negative (flatter). If A is unchanged, the intercept ln A is the same. A completely horizontal line would mean E<sub>a</sub> = 0.</p>');

// ---------- Extra mixed and conceptual ----------
mk(2, 'factors affecting rate', 'Which of these changes will NOT increase the rate of the gas phase reaction between H<sub>2</sub> and I<sub>2</sub> at a fixed temperature?', 'adding an inert gas at constant volume', ['increasing the concentration of H<sub>2</sub>', 'adding a catalyst', 'increasing the surface area of a solid catalyst'], '<p>Adding an inert gas at constant volume leaves the concentrations of H<sub>2</sub> and I<sub>2</sub> unchanged, so the rate is the same. The other changes increase the rate.</p>');
mk(3, 'mixed: kinetics and equilibrium', 'For a reversible reaction A &rightleftharpoons; B at equilibrium, which statement is correct?', 'the forward and reverse rates are equal and the equilibrium constant is k<sub>f</sub>/k<sub>r</sub>', ['both rates are zero', 'the forward rate is larger than the reverse rate', 'k<sub>f</sub> = k<sub>r</sub> always'], '<p>At equilibrium k<sub>f</sub>[A] = k<sub>r</sub>[B], so K = [B]/[A] = k<sub>f</sub>/k<sub>r</sub>. The reactions have not stopped; the rates are balanced.</p>');
mk(3, 'mixed: kinetics and thermodynamics', 'A reaction has a very large equilibrium constant (K &gt; 10<sup>20</sup>) but is extremely slow at room temperature. This shows that', 'thermodynamic feasibility does not guarantee a fast rate', ['the activation energy is negative', 'a catalyst cannot help', '&Delta;G&deg; is positive'], '<p>A large K means products are favoured (&Delta;G&deg; &lt; 0), but a high activation energy can still make the reaction slow. Diamond turning into graphite is a standard example. A catalyst can speed it up.</p>');
mk(3, 'graph reading', 'A plot of rate against [A] for a reaction is a horizontal straight line. The order with respect to A is', 'zero', ['one', 'two', 'one half'], '<p>Rate independent of [A] means rate = k[A]<sup>0</sup>, so the order is 0. A straight line through the origin would be first order, a parabola second order.</p>');
mk(3, 'graph reading', 'A plot of log(rate) against log[A] for a reaction is a straight line of slope 2. The order in A is', '2', ['1', '0.5', '4'], '<p>rate = k[A]<sup>n</sup> gives log rate = log k + n log[A]. The slope of the log-log plot is n = 2.</p>');
mk(4, 'mixed: electrochemistry and kinetics', 'An electrochemical cell with a very large E&deg;cell is short-circuited. The current is small because', 'the reaction at an electrode may be kinetically slow, though thermodynamically favoured', ['E&deg; is zero when short-circuited', 'electrons have no activation energy', 'the Nernst equation forbids a current'], '<p>E&deg; gives only the driving force, not the speed. A large overpotential (high activation energy for the electrode reaction) can make the current small. This links thermodynamics with kinetics.</p>');
mk(4, 'exponential decay', 'A radioactive sample has an initial activity of 8000 counts per minute. After 3 half-lives the activity will be', '1000 counts per minute', ['2667 counts per minute', '500 counts per minute', '4000 counts per minute'], '<p>Activity &prop; N, which halves each half-life: 8000 &rarr; 4000 &rarr; 2000 &rarr; 1000. A third of 8000 (2667) would wrongly use a linear fall.</p>');
mk(4, 'consecutive reactions', 'In A &rarr; B &rarr; C with k<sub>1</sub> much larger than k<sub>2</sub>, the overall rate of formation of C is controlled by', 'the second step, which is the slower one', ['the first step, which is the faster one', 'both steps equally', 'neither step'], '<p>Product C cannot form faster than B is converted. When k<sub>2</sub> is small, the second step is the rate-determining step and C forms at about k<sub>2</sub>[B].</p>');
mk(5, 'integrated rate laws', 'For a reaction, 1/[A] against t gives a straight line with a slope of 0.25 L mol<sup>-1</sup> s<sup>-1</sup> and [A]<sub>0</sub> = 2.0 M. What is the half-life?', '2.0 s', ['4.0 s', '8.0 s', '0.5 s'], '<p>A straight line in 1/[A] means second order, with k = slope = 0.25. t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>) = 1/(0.25 &times; 2.0) = <b>2.0 s</b>.</p>', 'Slope, not intercept, is k.');
mk(5, 'order from t1/2', 'The half-lives of a reaction are 40 min at [A]<sub>0</sub> = 0.20 M and 80 min at [A]<sub>0</sub> = 0.10 M. The rate constant is', '0.125 L mol<sup>-1</sup> min<sup>-1</sup>', ['0.025 min<sup>-1</sup>', '0.125 mol L<sup>-1</sup> min<sup>-1</sup>', '0.0025 L mol<sup>-1</sup> min<sup>-1</sup>'], '<p>Halving [A]<sub>0</sub> doubles t<sub>1/2</sub>, so t<sub>1/2</sub> &prop; 1/[A]<sub>0</sub>: second order. k = 1/(t<sub>1/2</sub>[A]<sub>0</sub>) = 1/(40 &times; 0.20) = 0.125 L mol<sup>-1</sup> min<sup>-1</sup>.</p>');

const groups = {
  m1: { title: 'Order and the unit of the rate constant', list1: ['A. Zero order', 'B. First order', 'C. Second order', 'D. Third order'], list2: ['p. mol L<sup>-1</sup> s<sup>-1</sup>', 'q. s<sup>-1</sup>', 'r. L mol<sup>-1</sup> s<sup>-1</sup>', 's. L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>'] },
  m2: { title: 'Order and half-life (single reactant)', list1: ['A. Zero order', 'B. First order', 'C. Second order', 'D. nth order (n &ne; 1)'], list2: ['p. t<sub>1/2</sub> = [A]<sub>0</sub>/2k', 'q. t<sub>1/2</sub> = 0.693/k', 'r. t<sub>1/2</sub> = 1/(k[A]<sub>0</sub>)', 's. t<sub>1/2</sub> proportional to [A]<sub>0</sub><sup>1-n</sup>'] },
  m3: { title: 'Straight-line plots and what they show', list1: ['A. [A] against t (straight line)', 'B. ln[A] against t (straight line)', 'C. 1/[A] against t (straight line)', 'D. ln k against 1/T (straight line)'], list2: ['p. zero order', 'q. first order', 'r. second order', 's. slope gives the activation energy'] },
  m4: { title: 'Observation and the main reason in collision theory', list1: ['A. Rate rises sharply with temperature', 'B. A catalyst speeds up a reaction', 'C. Many energetic collisions still do not react', 'D. Rate rises when concentration rises'], list2: ['p. More molecules have energy at least E<sub>a</sub>', 'q. A path with lower E<sub>a</sub> is available', 'r. Wrong orientation of molecules (steric factor)', 's. More collisions per second'] },
  p1: { title: 'Initial rates of A + B', passage: '<p>Initial rates were measured at constant temperature:</p><table><tr><th>Exp</th><th>[A] (M)</th><th>[B] (M)</th><th>rate (M s<sup>-1</sup>)</th></tr><tr><td>1</td><td>0.10</td><td>0.10</td><td>2.0 &times; 10<sup>-3</sup></td></tr><tr><td>2</td><td>0.20</td><td>0.10</td><td>8.0 &times; 10<sup>-3</sup></td></tr><tr><td>3</td><td>0.20</td><td>0.30</td><td>2.4 &times; 10<sup>-2</sup></td></tr></table>' },
  p2: { title: 'Decomposition of N<sub>2</sub>O<sub>5</sub>', passage: '<p>N<sub>2</sub>O<sub>5</sub> decomposes by a first order reaction in CCl<sub>4</sub> with k = 6.93 &times; 10<sup>-3</sup> min<sup>-1</sup> at a fixed temperature. Use ln 2 = 0.693.</p>' },
  p3: { title: 'Temperature dependence of a rate constant', passage: '<p>For a first order reaction, k = 2.0 &times; 10<sup>-3</sup> s<sup>-1</sup> at 300 K and k = 8.0 &times; 10<sup>-3</sup> s<sup>-1</sup> at 320 K. Take R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup> and log 4 = 0.602.</p>' },
};

// ---------- Templates ----------
const LOGS = { 2: 0.301, 3: 0.477, 4: 0.602, 5: 0.699 };
const kunit = (n) => (n === 0 ? 'mol L<sup>-1</sup> s<sup>-1</sup>' : n === 1 ? 's<sup>-1</sup>' : n === 2 ? 'L mol<sup>-1</sup> s<sup>-1</sup>' : n === 3 ? 'L<sup>2</sup> mol<sup>-2</sup> s<sup>-1</sup>' : n === 0.5 ? 'mol<sup>1/2</sup> L<sup>-1/2</sup> s<sup>-1</sup>' : 'L<sup>1/2</sup> mol<sup>-1/2</sup> s<sup>-1</sup>');
const RXN = [
  { eq: '2N<sub>2</sub>O<sub>5</sub> &rarr; 4NO<sub>2</sub> + O<sub>2</sub>', sp: [['N<sub>2</sub>O<sub>5</sub>', 2, 'disappears'], ['NO<sub>2</sub>', 4, 'forms'], ['O<sub>2</sub>', 1, 'forms']] },
  { eq: 'N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub>', sp: [['N<sub>2</sub>', 1, 'disappears'], ['H<sub>2</sub>', 3, 'disappears'], ['NH<sub>3</sub>', 2, 'forms']] },
  { eq: '4NH<sub>3</sub> + 5O<sub>2</sub> &rarr; 4NO + 6H<sub>2</sub>O', sp: [['NH<sub>3</sub>', 4, 'disappears'], ['O<sub>2</sub>', 5, 'disappears'], ['NO', 4, 'forms'], ['H<sub>2</sub>O', 6, 'forms']] },
  { eq: '2SO<sub>2</sub> + O<sub>2</sub> &rarr; 2SO<sub>3</sub>', sp: [['SO<sub>2</sub>', 2, 'disappears'], ['O<sub>2</sub>', 1, 'disappears'], ['SO<sub>3</sub>', 2, 'forms']] },
];
const pickTwo = (rng, a) => { const i = int(rng, 0, a.length - 1); let j = int(rng, 0, a.length - 2); if (j >= i) j++; return [a[i], a[j]]; };
const sciM = (x) => fmt(x, 3);

const gens = [
  { id: 'ck-g01', type: 'nat', level: 1, exams: EX[1], sub: 'rate and stoichiometry',
    make(rng) {
      const R = choose(rng, RXN); const [a, b] = pickTwo(rng, R.sp); const r = pick(rng, 2, 9, 1) / 10; const ans = r * b[1] / a[1];
      return { q: `For ${R.eq}, ${a[0]} ${a[2]} at ${r} mol L<sup>-1</sup> s<sup>-1</sup>. At what rate does ${b[0]} ${b[2] === 'forms' ? 'form' : 'disappear'} (mol L<sup>-1</sup> s<sup>-1</sup>)?`, answer: +ans.toFixed(3), tol: 0.005, unit: 'mol L<sup>-1</sup> s<sup>-1</sup>', r, ca: a[1], cb: b[1],
        sol: `<p>The rate of reaction is the same for every species once divided by its coefficient: rate(${a[0]})/${a[1]} = rate(${b[0]})/${b[1]}.</p><p>rate(${b[0]}) = ${r} &times; ${b[1]}/${a[1]} = <b>${ans.toFixed(3)}</b> mol L<sup>-1</sup> s<sup>-1</sup>.</p>` };
    }, verify: (p) => p.r * p.cb / p.ca },
  { id: 'ck-g02', type: 'nat', level: 2, exams: EX[2], sub: 'first order half-life',
    make(rng) {
      const t = choose(rng, [5, 10, 20, 25, 40, 50, 60, 80, 100]); const u = choose(rng, ['min', 's', 'h']); const k = 0.693 / t;
      return { q: `A first order reaction has a half-life of ${t} ${u}. Find its rate constant in ${u}<sup>-1</sup> (ln 2 = 0.693).`, answer: +k.toPrecision(3), tol: k * 0.01, unit: `${u}<sup>-1</sup>`, t,
        sol: `<p>k = 0.693/t<sub>1/2</sub> = 0.693/${t} = <b>${sciM(k)} ${u}<sup>-1</sup></b>.</p>` };
    }, verify: (p) => 0.693 / p.t },
  { id: 'ck-g03', type: 'nat', level: 2, exams: EX[2], sub: 'radioactive decay',
    make(rng) {
      const m = choose(rng, [16, 32, 64, 80, 128, 160, 200]); const th = choose(rng, [2, 3, 4, 5, 6, 8, 12]); const n = int(rng, 2, 5);
      const ans = m / 2 ** n;
      return { q: `A sample of ${m} g of a radioactive isotope has a half-life of ${th} days. What mass remains after ${n * th} days?`, answer: +ans.toPrecision(4), tol: ans * 0.005 + 1e-6, unit: 'g', m, n,
        sol: `<p>${n * th} days = ${n} half-lives. Mass = ${m} &times; (1/2)<sup>${n}</sup> = ${m}/${2 ** n} = <b>${sciM(ans)} g</b>.</p>` };
    }, verify: (p) => p.m * 0.5 ** p.n },
  { id: 'ck-g04', type: 'nat', level: 2, exams: EX[2], sub: 'first order integrated law',
    make(rng) {
      const x = choose(rng, [20, 25, 40, 60, 75, 80, 90]); const t = choose(rng, [10, 20, 30, 40, 50]);
      const lg = +Math.log10(100 / (100 - x)).toFixed(4); const k = 2.303 / t * lg;
      return { q: `In a first order reaction ${x} % of the reactant has reacted in ${t} min. Find k in min<sup>-1</sup>. (log ${(100 / (100 - x)).toFixed(3)} = ${lg})`, answer: +k.toPrecision(3), tol: k * 0.01, unit: 'min<sup>-1</sup>', t, lg,
        sol: `<p>[A]<sub>0</sub> = 100, [A] = ${100 - x}. k = (2.303/t) log([A]<sub>0</sub>/[A]) = (2.303/${t}) &times; ${lg}.</p><p>k = <b>${sciM(k)} min<sup>-1</sup></b>.</p>` };
    }, verify: (p) => 2.303 / p.t * p.lg },
  { id: 'ck-g05', type: 'nat', level: 2, exams: EX[2], sub: 'zero order',
    make(rng) {
      const A0 = choose(rng, [0.4, 0.5, 0.8, 1.0, 1.2, 2.0]); const k = choose(rng, [0.005, 0.01, 0.02, 0.04]); const f = choose(rng, [0.25, 0.5, 0.75]);
      const t = f * A0 / k;
      return { q: `A zero order reaction has k = ${k} mol L<sup>-1</sup> s<sup>-1</sup> and [A]<sub>0</sub> = ${A0} M. How long (in s) does it take for ${f * 100} % of A to react?`, answer: +t.toPrecision(4), tol: t * 0.005, unit: 's', A0, k, f,
        sol: `<p>Zero order: amount reacted = kt, so ${f * 100} % of ${A0} M = ${(f * A0).toFixed(3)} M = ${k} &times; t.</p><p>t = ${(f * A0).toFixed(3)}/${k} = <b>${sciM(t)} s</b>.</p>` };
    }, verify: (p) => p.f * p.A0 / p.k },
  { id: 'ck-g06', type: 'nat', level: 2, exams: EX[2], sub: 'second order integrated law',
    make(rng) {
      const A0 = choose(rng, [0.1, 0.2, 0.25, 0.5, 1.0]); const k = choose(rng, [0.1, 0.2, 0.5, 1.0, 2.0]); const t = choose(rng, [5, 10, 20, 50]);
      const inv = 1 / A0 + k * t; const A = 1 / inv;
      return { q: `A second order reaction (one reactant) has [A]<sub>0</sub> = ${A0} M and k = ${k} L mol<sup>-1</sup> s<sup>-1</sup>. Find [A] after ${t} s.`, answer: +A.toPrecision(3), tol: A * 0.01, unit: 'M', A0, k, t,
        sol: `<p>1/[A] = 1/[A]<sub>0</sub> + kt = ${(1 / A0).toFixed(2)} + ${k} &times; ${t} = ${inv.toFixed(2)} L/mol.</p><p>[A] = 1/${inv.toFixed(2)} = <b>${sciM(A)} M</b>.</p>` };
    }, verify: (p) => 1 / (1 / p.A0 + p.k * p.t) },
  { id: 'ck-g07', type: 'mcq', level: 2, exams: EXM[2], sub: 'units of k',
    make(rng) {
      const n = choose(rng, [0, 1, 2, 3, 0.5, 1.5]); const o = shuffleOpts(rng, kunit(n), [0, 1, 2, 3].filter((x) => x !== n).map(kunit));
      return { q: `The unit of the rate constant of a reaction of order ${n} (concentration in mol L<sup>-1</sup>, time in s) is`, options: o.options, answer: o.answer,
        sol: `<p>k = rate/[conc]<sup>n</sup>, so its unit is (mol L<sup>-1</sup>)<sup>1-n</sup> s<sup>-1</sup> = (mol L<sup>-1</sup>)<sup>${1 - n}</sup> s<sup>-1</sup>, which is <b>${kunit(n)}</b>.</p>` };
    } },
  { id: 'ck-g08', type: 'nat', level: 2, exams: EX[2], sub: 'effect of concentration on rate',
    make(rng) {
      const m = int(rng, 0, 3); const n = int(rng, 1, 2); const fa = choose(rng, [2, 3, 4]); const fb = choose(rng, [2, 3, 0.5]);
      const ans = fa ** m * fb ** n;
      return { q: `The rate law is rate = k[A]<sup>${m}</sup>[B]<sup>${n}</sup>. By what factor does the rate change when [A] is multiplied by ${fa} and [B] is multiplied by ${fb}?`, answer: ans, tol: ans * 0.005, m, n, fa, fb,
        sol: `<p>Rate factor = ${fa}<sup>${m}</sup> &times; ${fb}<sup>${n}</sup> = ${fa ** m} &times; ${fb ** n} = <b>${fmt(ans, 4)}</b>.</p>` };
    }, verify: (p) => p.fa ** p.m * p.fb ** p.n },
  { id: 'ck-g09', type: 'nat', level: 3, exams: EX[3], sub: 'initial rate method',
    make(rng) {
      const m = int(rng, 0, 2); const n = int(rng, 1, 2); const k = pick(rng, 1, 9, 1) * choose(rng, [0.1, 1, 10]); const a = choose(rng, [0.1, 0.2]); const b = choose(rng, [0.1, 0.2]);
      const f = choose(rng, [2, 3]);
      const rt = (x, y) => k * x ** m * y ** n;
      return { q: `For A + B &rarr; products, initial rates were: (i) [A] = ${a} M, [B] = ${b} M, rate = ${fmt(rt(a, b), 4)} M s<sup>-1</sup>; (ii) [A] = ${f * a} M, [B] = ${b} M, rate = ${fmt(rt(f * a, b), 4)} M s<sup>-1</sup>; (iii) [A] = ${a} M, [B] = ${f * b} M, rate = ${fmt(rt(a, f * b), 4)} M s<sup>-1</sup>. Find the rate constant k (in ${kunit(m + n)}); the orders are whole numbers.`, answer: +k.toPrecision(3), tol: k * 0.01, unit: kunit(m + n), m, n, k, a, b,
        sol: `<p>(i) to (ii): [A] &times; ${f}, rate &times; ${f ** m}, so the order in A is ${m}. (i) to (iii): [B] &times; ${f}, rate &times; ${f ** n}, so the order in B is ${n}.</p><p>k = rate/([A]<sup>${m}</sup>[B]<sup>${n}</sup>) = ${fmt(rt(a, b), 4)}/(${a}<sup>${m}</sup> &times; ${b}<sup>${n}</sup>) = <b>${sciM(k)}</b> ${kunit(m + n)}.</p>` };
    }, verify: (p) => p.k * p.a ** p.m * p.b ** p.n / (p.a ** p.m * p.b ** p.n) },
  { id: 'ck-g10', type: 'nat', level: 3, exams: EX[3], sub: 'activation energy',
    make(rng) {
      const T1 = choose(rng, [300, 310, 320]); const dT = choose(rng, [10, 20, 30]); const T2 = T1 + dT; const r = choose(rng, [2, 3, 4, 5]);
      const Ea = 2.303 * 8.314 * LOGS[r] * T1 * T2 / dT / 1000;
      return { q: `The rate constant of a reaction becomes ${r} times larger when the temperature is raised from ${T1} K to ${T2} K. Find E<sub>a</sub> in kJ/mol (R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup>, log ${r} = ${LOGS[r]}).`, answer: +Ea.toPrecision(3), tol: Ea * 0.01, unit: 'kJ/mol', T1, T2, r,
        sol: `<p>E<sub>a</sub> = 2.303 R log(k<sub>2</sub>/k<sub>1</sub>) &times; T<sub>1</sub>T<sub>2</sub>/(T<sub>2</sub> - T<sub>1</sub>) = 2.303 &times; 8.314 &times; ${LOGS[r]} &times; (${T1} &times; ${T2}/${dT}).</p><p>= <b>${sciM(Ea)} kJ/mol</b>.</p>` };
    }, verify: (p) => 2.303 * 8.314 * { 2: 0.301, 3: 0.477, 4: 0.602, 5: 0.699 }[p.r] * p.T1 * p.T2 / (p.T2 - p.T1) / 1000 },
  { id: 'ck-g11', type: 'nat', level: 3, exams: EX[3], sub: 'Arrhenius equation',
    make(rng) {
      const Ea = choose(rng, [40, 50, 60, 70, 80]); const T1 = choose(rng, [290, 300, 310]); const T2 = T1 + choose(rng, [10, 20]);
      const f = Math.exp(Ea * 1000 / 8.314 * (1 / T1 - 1 / T2));
      return { q: `A reaction has E<sub>a</sub> = ${Ea} kJ/mol. By what factor does its rate constant increase when the temperature goes from ${T1} K to ${T2} K? (R = 8.314)`, answer: +f.toPrecision(3), tol: f * 0.02, Ea, T1, T2,
        sol: `<p>ln(k<sub>2</sub>/k<sub>1</sub>) = (E<sub>a</sub>/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (${Ea * 1000}/8.314)(1/${T1} - 1/${T2}) = ${Math.log(f).toFixed(3)}.</p><p>k<sub>2</sub>/k<sub>1</sub> = e<sup>${Math.log(f).toFixed(3)}</sup> = <b>${sciM(f)}</b>.</p>` };
    }, verify: (p) => Math.exp(p.Ea * 1000 / 8.314 * (1 / p.T1 - 1 / p.T2)) },
  { id: 'ck-g12', type: 'nat', level: 3, exams: EX[3], sub: 'first order',
    make(rng) {
      const x = choose(rng, [50, 75, 90, 99]); const k = choose(rng, [0.01, 0.02, 0.05, 0.1]);
      const lg = Math.log10(100 / (100 - x)); const t = 2.303 / k * lg;
      return { q: `A first order reaction has k = ${k} min<sup>-1</sup>. How long (in min) does it take for ${x} % of the reactant to be consumed? (log ${(100 / (100 - x)).toFixed(0)} = ${lg.toFixed(3)})`, answer: +t.toPrecision(3), tol: t * 0.01, unit: 'min', k, lg,
        sol: `<p>t = (2.303/k) log([A]<sub>0</sub>/[A]) = (2.303/${k}) &times; ${lg.toFixed(3)} = <b>${sciM(t)} min</b>.</p>` };
    }, verify: (p) => 2.303 / p.k * p.lg },
  { id: 'ck-g13', type: 'nat', level: 3, exams: EX[3], sub: 'gaseous first order',
    make(rng) {
      const P0 = choose(rng, [100, 200, 400]); const r = choose(rng, [2, 4, 5]); const pA = P0 / r; const Pt = 2 * P0 - pA; const t = choose(rng, [10, 20, 25, 50]);
      const k = 2.303 / t * LOGS[r === 4 ? 4 : r === 2 ? 2 : 5];
      return { q: `A(g) &rarr; B(g) + C(g) is first order. Starting with pure A at ${P0} mmHg, the total pressure is ${Pt} mmHg after ${t} min. Find k in min<sup>-1</sup> (log ${r} = ${LOGS[r]}).`, answer: +k.toPrecision(3), tol: k * 0.01, unit: 'min<sup>-1</sup>', t, r,
        sol: `<p>If p of A reacts, total pressure = P<sub>0</sub> + p, so p = ${Pt} - ${P0} = ${Pt - P0}. P(A) = ${P0} - ${Pt - P0} = ${pA} mmHg.</p><p>k = (2.303/${t}) log(${P0}/${pA}) = (2.303/${t}) &times; ${LOGS[r]} = <b>${sciM(k)} min<sup>-1</sup></b>.</p>` };
    }, verify: (p) => 2.303 / p.t * { 2: 0.301, 4: 0.602, 5: 0.699 }[p.r] },
  { id: 'ck-g14', type: 'mcq', level: 3, exams: EXM[3], sub: 'order from data',
    make(rng) {
      const f = choose(rng, [2, 3]); const n = int(rng, 0, 3); const X = f ** n; const names = ['zero', 'first', 'second', 'third'];
      const o = shuffleOpts(rng, names[n], names.filter((x, i) => i !== n));
      return { q: `For a reaction of a single reactant A, the initial rate becomes ${X} times when [A] is multiplied by ${f}. The order of the reaction is`, options: o.options, answer: o.answer,
        sol: `<p>Rate &prop; [A]<sup>n</sup>, so ${f}<sup>n</sup> = ${X}, which gives n = ${n}. The reaction is <b>${names[n]}</b> order.</p>` };
    } },
  { id: 'ck-g15', type: 'nat', level: 3, exams: EX[3], sub: 'radioactive dating',
    make(rng) {
      const th = choose(rng, [5730, 1620, 4.5e3, 24100, 138]); const n = int(rng, 2, 5); const t = n * th;
      return { q: `A sample has ${(100 / 2 ** n).toPrecision(3)} % of its original number of radioactive atoms left. The half-life is ${th} years. How old is the sample (in years)?`, answer: t, tol: t * 0.005, unit: 'years', th, n,
        sol: `<p>${(100 / 2 ** n).toPrecision(3)} % = (1/2)<sup>${n}</sup>, so ${n} half-lives have passed.</p><p>Age = ${n} &times; ${th} = <b>${t} years</b>.</p>` };
    }, verify: (p) => p.n * p.th },
  { id: 'ck-g16', type: 'nat', level: 4, exams: EX[4], sub: 'parallel reactions',
    make(rng) {
      const k1 = pick(rng, 1, 9, 1) * 1e-3; const k2 = pick(rng, 1, 9, 1) * 1e-3; const ans = k1 / (k1 + k2) * 100;
      return { q: `A reacts by two parallel first order paths to give B (k<sub>1</sub> = ${k1 * 1000} &times; 10<sup>-3</sup> s<sup>-1</sup>) and C (k<sub>2</sub> = ${k2 * 1000} &times; 10<sup>-3</sup> s<sup>-1</sup>). What percentage of the reacted A becomes B?`, answer: +ans.toPrecision(3), tol: ans * 0.01, unit: '%', k1, k2,
        sol: `<p>Products form in the ratio of the rate constants, so fraction of B = k<sub>1</sub>/(k<sub>1</sub> + k<sub>2</sub>) = ${k1 * 1000}/(${k1 * 1000} + ${k2 * 1000}) = <b>${sciM(ans)} %</b>.</p>` };
    }, verify: (p) => p.k1 / (p.k1 + p.k2) * 100 },
  { id: 'ck-g17', type: 'nat', level: 4, exams: EX[4], sub: 'consecutive reactions',
    make(rng) {
      const r = choose(rng, [2, 3, 4, 5]); const k2 = choose(rng, [0.05, 0.1, 0.2]); const k1 = r * k2; const LN = { 2: 0.693, 3: 1.099, 4: 1.386, 5: 1.609 };
      const t = LN[r] / (k1 - k2);
      return { q: `In A &rarr; B &rarr; C (both first order) k<sub>1</sub> = ${k1.toFixed(2)} min<sup>-1</sup> and k<sub>2</sub> = ${k2} min<sup>-1</sup>. The concentration of B is highest at t = ln(k<sub>1</sub>/k<sub>2</sub>)/(k<sub>1</sub> - k<sub>2</sub>). Find this time in min (ln ${r} = ${LN[r]}).`, answer: +t.toPrecision(3), tol: t * 0.01, unit: 'min', k1, k2, r,
        sol: `<p>t<sub>max</sub> = ln(${k1.toFixed(2)}/${k2})/(${k1.toFixed(2)} - ${k2}) = ${LN[r]}/${(k1 - k2).toFixed(2)} = <b>${sciM(t)} min</b>.</p>` };
    }, verify: (p) => ({ 2: 0.693, 3: 1.099, 4: 1.386, 5: 1.609 }[p.r]) / (p.k1 - p.k2) },
  { id: 'ck-g18', type: 'nat', level: 4, exams: EX[4], sub: 'Arrhenius equation',
    make(rng) {
      const e = int(rng, 10, 14); const Ea = choose(rng, [60, 70, 80, 90, 100]); const T = choose(rng, [300, 320, 350]);
      const k = 10 ** e * Math.exp(-Ea * 1000 / (8.314 * T)); const ex = Math.floor(Math.log10(k)); const m = k / 10 ** ex;
      return { q: `A reaction has A = 1 &times; 10<sup>${e}</sup> s<sup>-1</sup> and E<sub>a</sub> = ${Ea} kJ/mol. Find k at ${T} K, giving the number before the power of ten as shown (k = x &times; 10<sup>${ex}</sup> s<sup>-1</sup>; find x). R = 8.314.`, answer: +m.toPrecision(3), tol: m * 0.03, unit: `&times; 10<sup>${ex}</sup> s<sup>-1</sup>`, e, Ea, T, ex,
        sol: `<p>E<sub>a</sub>/RT = ${Ea * 1000}/(8.314 &times; ${T}) = ${(Ea * 1000 / (8.314 * T)).toFixed(2)}. e<sup>-${(Ea * 1000 / (8.314 * T)).toFixed(2)}</sup> = ${fmt(Math.exp(-Ea * 1000 / (8.314 * T)), 3)}.</p><p>k = 10<sup>${e}</sup> &times; ${fmt(Math.exp(-Ea * 1000 / (8.314 * T)), 3)} = ${fmt(k, 3)} s<sup>-1</sup>, so x = <b>${sciM(m)}</b>.</p>` };
    }, verify: (p) => 10 ** p.e * Math.exp(-p.Ea * 1000 / (8.314 * p.T)) / 10 ** p.ex },
  { id: 'ck-g19', type: 'nat', level: 4, exams: EX[4], sub: 'pseudo first order',
    make(rng) {
      const B = choose(rng, [0.5, 1.0, 2.0]); const th = choose(rng, [10, 20, 25, 50, 100]); const k = 0.693 / th / B;
      return { q: `For A + B &rarr; products (rate = k[A][B]) the half-life of A is ${th} s when [B]<sub>0</sub> = ${B} M and [A]<sub>0</sub> = 1 &times; 10<sup>-3</sup> M. Find k in L mol<sup>-1</sup> s<sup>-1</sup> (ln 2 = 0.693).`, answer: +k.toPrecision(3), tol: k * 0.01, unit: 'L mol<sup>-1</sup> s<sup>-1</sup>', th, B,
        sol: `<p>B is in large excess, so the reaction is pseudo first order with k&prime; = k[B]<sub>0</sub> = 0.693/${th} = ${fmt(0.693 / th, 3)} s<sup>-1</sup>.</p><p>k = k&prime;/[B]<sub>0</sub> = ${fmt(0.693 / th, 3)}/${B} = <b>${sciM(k)} L mol<sup>-1</sup> s<sup>-1</sup></b>.</p>` };
    }, verify: (p) => 0.693 / p.th / p.B },
  { id: 'ck-g20', type: 'nat', level: 4, exams: EX[4], sub: 'effect of catalyst',
    make(rng) {
      const Ea = choose(rng, [60, 70, 80, 90]); const d = choose(rng, [10, 15, 20, 25]); const T = choose(rng, [300, 320, 350]);
      const lg = d * 1000 / (2.303 * 8.314 * T);
      return { q: `A catalyst lowers E<sub>a</sub> from ${Ea} to ${Ea - d} kJ/mol at ${T} K, with A unchanged. Find log<sub>10</sub> of the factor by which k increases (R = 8.314).`, answer: +lg.toFixed(2), tol: 0.03, d, T,
        sol: `<p>k&prime;/k = e<sup>&Delta;E<sub>a</sub>/RT</sup>, so log(k&prime;/k) = ${d * 1000}/(2.303 &times; 8.314 &times; ${T}) = <b>${lg.toFixed(2)}</b>.</p>` };
    }, verify: (p) => p.d * 1000 / (2.303 * 8.314 * p.T) },
  { id: 'ck-g21', type: 'mcq', level: 3, exams: EXM[3], sub: 'straight-line plots',
    make(rng) {
      const t = choose(rng, [['zero', '[A] against t'], ['first', 'ln[A] against t'], ['second', '1/[A] against t']]);
      const names = ['zero', 'first', 'second', 'third']; const o = shuffleOpts(rng, t[0], names.filter((x) => x !== t[0]).slice(0, 3));
      const o2 = { options: o.options.map((x) => `${x} order`), answer: o.answer };
      return { q: `A plot of ${t[1]} is a straight line for a single-reactant reaction. The reaction is of`, options: o2.options, answer: o2.answer,
        sol: `<p>Zero order: [A] = [A]<sub>0</sub> - kt. First order: ln[A] = ln[A]<sub>0</sub> - kt. Second order: 1/[A] = 1/[A]<sub>0</sub> + kt.</p><p>A straight line in ${t[1]} means <b>${t[0]} order</b>.</p>` };
    } },
  { id: 'ck-g22', type: 'nat', level: 5, exams: EX[5], sub: 'opposing reactions',
    make(rng) {
      const kf = choose(rng, [0.02, 0.03, 0.04, 0.06]); const kr = choose(rng, [0.01, 0.02]); const t = 0.693 / (kf + kr);
      return { q: `A &rightleftharpoons; B has first order forward rate constant ${kf} min<sup>-1</sup> and reverse rate constant ${kr} min<sup>-1</sup>. The approach to equilibrium is first order with rate constant k<sub>f</sub> + k<sub>r</sub>. Find the time (min) in which the distance from equilibrium halves (ln 2 = 0.693).`, answer: +t.toPrecision(3), tol: t * 0.01, unit: 'min', kf, kr,
        sol: `<p>k<sub>eff</sub> = ${kf} + ${kr} = ${(kf + kr).toFixed(2)} min<sup>-1</sup>. t = 0.693/${(kf + kr).toFixed(2)} = <b>${sciM(t)} min</b>. (K = k<sub>f</sub>/k<sub>r</sub> = ${fmt(kf / kr, 3)}.)</p>` };
    }, verify: (p) => 0.693 / (p.kf + p.kr) },
  { id: 'ck-g23', type: 'nat', level: 2, exams: EX[2], sub: 'temperature coefficient',
    make(rng) {
      const mu = choose(rng, [2, 3]); const dT = choose(rng, [20, 30, 40, 50]); const ans = mu ** (dT / 10);
      return { q: `The rate of a reaction becomes ${mu} times for every 10 K rise in temperature. By what factor does the rate change for a ${dT} K rise?`, answer: ans, tol: 0, mu, dT,
        sol: `<p>${dT / 10} steps of 10 K, each multiplying the rate by ${mu}: ${mu}<sup>${dT / 10}</sup> = <b>${ans}</b>.</p>` };
    }, verify: (p) => p.mu ** (p.dT / 10) },
  { id: 'ck-g24', type: 'nat', level: 3, exams: EX[3], sub: 'half-life by order',
    make(rng) {
      const n = choose(rng, [0, 1, 2]); const A0 = choose(rng, [0.2, 0.4, 0.5, 1.0]); const k = n === 0 ? choose(rng, [0.01, 0.02, 0.05]) : n === 1 ? choose(rng, [0.01, 0.02, 0.0693]) : choose(rng, [0.1, 0.25, 0.5]);
      const t = n === 0 ? A0 / (2 * k) : n === 1 ? 0.693 / k : 1 / (k * A0);
      return { q: `A reaction of order ${n} has k = ${k} ${kunit(n)} and [A]<sub>0</sub> = ${A0} M (single reactant). Find the half-life in seconds (ln 2 = 0.693).`, answer: +t.toPrecision(3), tol: t * 0.01, unit: 's', n, k, A0,
        sol: `<p>${n === 0 ? 't<sub>1/2</sub> = [A]<sub>0</sub>/2k' : n === 1 ? 't<sub>1/2</sub> = 0.693/k' : 't<sub>1/2</sub> = 1/(k[A]<sub>0</sub>)'} for order ${n}.</p><p>t<sub>1/2</sub> = <b>${sciM(t)} s</b>.</p>` };
    }, verify: (p) => (p.n === 0 ? p.A0 / (2 * p.k) : p.n === 1 ? 0.693 / p.k : 1 / (p.k * p.A0)) },
];

